//! The reference parser on real bibliographies: the layout parser's bibliography blocks
//! of seven public arXiv papers (`fixtures/corpus_references.json`, built by
//! [`super::corpus_dump`]), segmented and parsed, with a hand-labelled sample across the
//! styles they use (ICML/NeurIPS author–title–year, numbered NeurIPS, ACL-like author-first,
//! quoted titles) and floors on how much of each bibliography is read.

use serde_json::Value;

use super::reference::{parse_reference, ParsedReference};
use super::segment::{segment, BibBlock};

const FIXTURE: &str = include_str!("fixtures/corpus_references.json");

fn papers() -> Vec<(String, Vec<ParsedReference>, usize)> {
    let all: Value = serde_json::from_str(FIXTURE).unwrap();
    let mut out = Vec::new();
    for (name, paper) in all.as_object().unwrap() {
        let blocks: Vec<BibBlock> = paper["references"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| BibBlock {
                text: r["text"].as_str().unwrap().to_string(),
                page: r["page"].as_u64().map(|p| p as u32),
                bbox: None,
                section_path: r["section"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|s| s.as_str().unwrap().to_string())
                    .collect(),
            })
            .collect();
        let s = segment(&blocks);
        let parsed = s.entries.iter().map(|e| parse_reference(&e.text)).collect();
        out.push((name.clone(), parsed, s.rejected.len()));
    }
    out
}

fn find<'a>(refs: &'a [ParsedReference], needle: &str) -> &'a ParsedReference {
    refs.iter()
        .find(|r| r.text.contains(needle))
        .unwrap_or_else(|| panic!("no entry contains {needle:?}"))
}

/// `(paper prefix, text in the entry, title, year, first surname, arXiv id)`.
const LABELLED: &[(&str, &str, &str, i32, &str, Option<&str>)] = &[
    ("2102.11174", "Ba, J., Hinton", "Using fast weights to attend to the recent past", 2016, "ba", None),
    ("2102.11174", "Baevski, A. and Auli", "Adaptive input representations for neural language modeling", 2019, "baevski", None),
    ("2406.06484", "Akyürek", "In-context language learning: Arhitectures and algorithms", 2024, "akyurek", Some("2401.12973")),
    ("2406.06484", "Aksenov", "Linear Transformers with Learnable Kernel Functions are Better In-Context Models", 2024, "aksenov", Some("2402.10644")),
    ("2406.06484", "The hidden attention of mamba", "The hidden attention of mamba models", 2024, "ali", None),
    ("2411.12537", "William Merrill, Jackson Petty", "The Illusion of State in State-Space Models", 2024, "merrill", None),
    ("2411.12537", "Satwik Bhattamishra", "On the ability and limitations of transformers to recognize formal languages", 2020, "bhattamishra", None),
    ("2505.01730", "Stochastic gradient descent tricks", "Stochastic gradient descent tricks", 2012, "bottou", None),
    ("2505.01730", "Optimal ann-snn conversion", "Optimal ann-snn conversion for high-accuracy and ultra-low-latency spiking neural networks", 2023, "bu", Some("2303.04347")),
    ("2505.01730", "Spatio-temporal backpropagation", "Spatio-temporal backpropagation for training high-performance spiking neural networks", 2018, "wu", None),
    ("2407.04620", "Gpt-4 technical report", "Gpt-4 technical report", 2023, "achiam", Some("2303.08774")),
    ("2407.04620", "Self-supervised policy adaptation", "Self-supervised policy adaptation during deployment", 2020, "hansen", Some("2007.04309")),
    ("2504.13173", "Unsupervised Representation Learning of Brain Activity", "Unsupervised Representation Learning of Brain Activity via Bridging Voxel Activity and Functional Connectivity", 2024, "behrouz", None),
    ("2504.13173", "Scaling laws for neural language models", "Scaling laws for neural language models", 2020, "kaplan", Some("2001.08361")),
    ("2605.04308", "Gpt-4 technical report", "Gpt-4 technical report", 2023, "achiam", Some("2303.08774")),
    ("2605.04308", "From self-attention to markov models", "From self-attention to markov models: Unveiling the dynamics of generative transformers", 2024, "ildiz", Some("2402.13512")),
];

#[test]
fn the_hand_labelled_sample_parses_field_by_field() {
    let papers = papers();
    let mut wrong = Vec::new();
    for (paper, needle, title, year, surname, arxiv) in LABELLED {
        let (_, refs, _) = papers
            .iter()
            .find(|(name, _, _)| name.starts_with(paper))
            .unwrap();
        let r = find(refs, needle);
        if r.title.as_deref() != Some(*title) {
            wrong.push(format!("{paper} {needle}: title {:?}", r.title));
        }
        if r.year != Some(*year) {
            wrong.push(format!("{paper} {needle}: year {:?}", r.year));
        }
        if r.first_surname().as_deref() != Some(*surname) {
            wrong.push(format!(
                "{paper} {needle}: first surname {:?}",
                r.first_surname()
            ));
        }
        if r.arxiv_id.as_deref() != *arxiv {
            wrong.push(format!("{paper} {needle}: arXiv {:?}", r.arxiv_id));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} of {} fields wrong:\n{}",
        wrong.len(),
        LABELLED.len() * 4,
        wrong.join("\n")
    );
}

#[test]
fn most_of_every_bibliography_is_read() {
    let mut total = 0;
    let mut identifiable = 0;
    let mut with_title_year = 0;
    let mut with_authors = 0;
    for (name, refs, rejected) in papers() {
        let n = refs.len();
        let id = refs.iter().filter(|r| r.is_identifiable()).count();
        let ty = refs
            .iter()
            .filter(|r| r.title.is_some() && r.year.is_some())
            .count();
        let au = refs.iter().filter(|r| !r.authors.is_empty()).count();
        println!("{name}: {n} entries, {rejected} rejected blocks, {id} identifiable, {ty} with title and year, {au} with authors");
        assert!(n >= 30, "{name}: only {n} entries");
        assert!(id * 100 >= n * 90, "{name}: {id} of {n} identifiable");
        total += n;
        identifiable += id;
        with_title_year += ty;
        with_authors += au;
    }
    println!("all: {total} entries, {identifiable} identifiable, {with_title_year} with title and year, {with_authors} with authors");
    assert!(
        with_title_year * 100 >= total * 90,
        "{with_title_year} of {total} with title and year"
    );
    assert!(
        with_authors * 100 >= total * 90,
        "{with_authors} of {total} with authors"
    );
}

//! Graph builds against a real statement store (LanceDB + SQLite in a temporary folder),
//! with scans made in the test and OpenAlex answers replayed from recorded JSON.

use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::time::Duration;

use super::identity::LocalIdentity;
use super::reference::parse_reference;
use super::resolve::tests::{fixture, Replay};
use super::resolve::{Resolver, WorkRequest};
use super::scan::{PaperScan, ScannedReference, SCAN_VERSION};
use super::service::{CitationService, GraphSlot, ScanCounts};
use crate::research::db::ResearchDb;
use crate::research::results::ResultService;
use crate::statements::testing::{t0, FixedEmbedder, TestClock, WordEmbedder};
use crate::statements::{DynamicsStore, StatementQuery, StatementStore};

struct Fixture {
    _dir: tempfile::TempDir,
    store: Arc<StatementStore>,
    db: Arc<ResearchDb>,
    results: ResultService,
}

async fn fixture_store() -> Fixture {
    let dir = tempfile::tempdir().unwrap();
    let ontology = Arc::new(shodh_ontology::Ontology::builtin_with_packs(&["research"]).unwrap());
    let dynamics = Arc::new(DynamicsStore::open(&dir.path().join("shodh.db"), None).unwrap());
    let store = Arc::new(
        StatementStore::open(
            &dir.path().join("lance"),
            crate::statements::testing::DIM,
            ontology,
            dynamics,
            Arc::new(FixedEmbedder(Arc::new(WordEmbedder::default()))),
            TestClock::at(t0()),
        )
        .await
        .unwrap(),
    );
    let db = Arc::new(ResearchDb::open(&dir.path().join("shodh.db"), None).unwrap());
    let results = ResultService::new(store.clone(), db.clone(), "test");
    Fixture {
        _dir: dir,
        store,
        db,
        results,
    }
}

fn scan(path: &str, title: &str, arxiv: Option<&str>, refs: &[&str]) -> PaperScan {
    PaperScan {
        version: SCAN_VERSION.into(),
        file_path: path.into(),
        identity: LocalIdentity {
            title: Some(title.into()),
            arxiv_id: arxiv.map(str::to_string),
            ..LocalIdentity::default()
        },
        references: refs
            .iter()
            .enumerate()
            .map(|(index, text)| ScannedReference {
                index,
                page: Some(9),
                regions: Vec::new(),
                parsed: parse_reference(text),
            })
            .collect(),
        rejected: Vec::new(),
        truncated: 0,
        headings: Vec::new(),
        captions: Vec::new(),
        pages: 10,
    }
}

const LSTM: &str = "Hochreiter, S. and Schmidhuber, J. Long short-term memory. Neural Computation, 9(8):1735–1780, 1997. doi:10.1162/neco.1997.9.8.1735";
const FWP: &str = "Schlag, I., Irie, K., and Schmidhuber, J. Linear transformers are secretly fast weight programmers. In ICML, 2021.";

fn library() -> Vec<PaperScan> {
    vec![
        scan(
            "C:/p/delta.pdf",
            "Delta rule transformers",
            Some("2406.06484"),
            &[LSTM, FWP],
        ),
        scan(
            "C:/p/fwp.pdf",
            "Linear transformers are secretly fast weight programmers",
            None,
            &[LSTM],
        ),
    ]
}

fn nothing(_: super::service::BuildProgress) {}

async fn graph_statements(store: &StatementStore) -> Vec<crate::statements::StoredStatement> {
    store
        .query(&StatementQuery {
            classes: vec![
                "Paper".into(),
                "Author".into(),
                "Venue".into(),
                "Method".into(),
            ],
            limit: Some(500),
            ..StatementQuery::default()
        })
        .await
        .unwrap()
}

#[tokio::test]
async fn a_local_build_stores_the_graph_and_a_rebuild_writes_nothing() {
    let f = fixture_store().await;
    let service = CitationService::new(f.store.clone(), f.db.clone(), GraphSlot::default());
    let offline = Resolver::cache_only(f.db.clone());
    let report = service
        .build_from_scans(
            library(),
            ScanCounts::default(),
            &f.results,
            &offline,
            &nothing,
        )
        .await
        .unwrap();
    assert!(!report.online);
    assert_eq!(
        report.lookups.map(|l| l.requests),
        Some(0),
        "local-only builds send nothing"
    );
    assert_eq!(report.size.library_papers, 2);
    assert_eq!(report.size.papers, 3, "LSTM once, FWP is the library paper");
    assert_eq!(report.size.cites, 3);
    assert_eq!(report.references_linked_to_library, 1);
    assert!(report.added >= 3);
    assert_eq!(report.updated + report.removed + report.refused, 0);

    let graph = service.graph(&f.results).await.unwrap();
    let delta = graph.paper("paper:arxiv:2406.06484").unwrap();
    assert!(delta.in_library && delta.statement_id.is_some());
    let fwp = graph.paper_for_file("C:/p/fwp.pdf").unwrap();
    assert_eq!(graph.citers(&fwp.id).len(), 1);
    assert!(graph
        .evidence(&delta.id, &fwp.id)
        .unwrap()
        .text
        .contains("fast weight"));

    let again = service
        .build_from_scans(
            library(),
            ScanCounts::default(),
            &f.results,
            &offline,
            &nothing,
        )
        .await
        .unwrap();
    assert_eq!((again.added, again.updated, again.removed), (0, 0, 0));
    assert_eq!(again.unchanged, report.added);

    // The graph reads back from the store in a new session, evidence included.
    let fresh = CitationService::new(f.store.clone(), f.db.clone(), GraphSlot::default());
    let loaded = fresh.graph(&f.results).await.unwrap();
    assert_eq!(loaded.size().papers, 3);
    assert_eq!(loaded.size().cites, 3);
    assert!(loaded.evidence(&delta.id, &fwp.id).is_some());
}

#[tokio::test]
async fn a_dropped_reference_supersedes_the_paper_and_forgets_the_orphan() {
    let f = fixture_store().await;
    let service = CitationService::new(f.store.clone(), f.db.clone(), GraphSlot::default());
    let offline = Resolver::cache_only(f.db.clone());
    service
        .build_from_scans(
            library(),
            ScanCounts::default(),
            &f.results,
            &offline,
            &nothing,
        )
        .await
        .unwrap();
    let mut changed = library();
    changed[0].references.remove(0);
    changed[1].references.clear();
    let report = service
        .build_from_scans(
            changed,
            ScanCounts::default(),
            &f.results,
            &offline,
            &nothing,
        )
        .await
        .unwrap();
    assert_eq!(report.updated, 2, "both library papers changed their cites");
    assert!(report.removed >= 1, "LSTM is no longer cited");
    assert_eq!(report.size.papers, 2);
    let stored = graph_statements(&f.store).await;
    assert!(!stored.iter().any(|s| s
        .statement
        .subject
        .as_ref()
        .is_some_and(|e| e.id.contains("neco"))));
    let delta = stored
        .iter()
        .find(|s| {
            s.statement
                .subject
                .as_ref()
                .is_some_and(|e| e.id == "paper:arxiv:2406.06484")
        })
        .unwrap();
    // History keeps the old version.
    let history = f.store.history_ids(delta.id()).await.unwrap();
    assert_eq!(history.len(), 2);
}

#[tokio::test]
async fn online_builds_match_by_identifier_once_and_reuse_the_cache() {
    let f = fixture_store().await;
    let service = CitationService::new(f.store.clone(), f.db.clone(), GraphSlot::default());
    let lstm = WorkRequest::Doi("10.1162/neco.1997.9.8.1735".into());
    let replay = Arc::new(Replay::new(vec![(lstm, 200, fixture("work_by_doi"))]));
    let online = Resolver::online(replay.clone(), f.db.clone()).with_limits(50, Duration::ZERO);
    let report = service
        .build_from_scans(
            library(),
            ScanCounts::default(),
            &f.results,
            &online,
            &nothing,
        )
        .await
        .unwrap();
    assert!(report.online);
    assert_eq!(report.references_resolved, 2, "LSTM in both papers");
    let graph = service.graph(&f.results).await.unwrap();
    let node = graph.paper("paper:doi:10.1162/neco.1997.9.8.1735").unwrap();
    assert_eq!(node.openalex_id.as_deref(), Some("W2064675550"));
    assert!(node.cited_by_count.unwrap_or(0) > 1000);
    let first = replay.requests.load(Ordering::SeqCst);
    assert!(
        first >= 2,
        "the library paper's arXiv id and the DOI were asked"
    );

    let online = Resolver::online(replay.clone(), f.db.clone()).with_limits(50, Duration::ZERO);
    let again = service
        .build_from_scans(
            library(),
            ScanCounts::default(),
            &f.results,
            &online,
            &nothing,
        )
        .await
        .unwrap();
    assert_eq!(
        replay.requests.load(Ordering::SeqCst),
        first,
        "every answer came from the cache"
    );
    assert_eq!((again.added, again.updated), (0, 0));
}

