import React, { forwardRef, useCallback, useImperativeHandle, useLayoutEffect, useRef } from 'react';
import { ArrowUp, CornerDownRight, Folder, ImagePlus, Mic, MicOff, Square } from 'lucide-react';
import { cn } from '../../lib/utils';
import { useVoiceInput } from '../ask/useVoiceInput';
import { pasteDecision } from '../ask/imageNotice';

/** The engine grows the field with its content (no per-keystroke measuring). */
const NATIVE_FIELD_SIZING = typeof CSS !== 'undefined' && CSS.supports('field-sizing', 'content');
const MIN_COMPACT_HEIGHT = 32;
const MIN_TEXTAREA_HEIGHT = 66;

const FOCUS_RING =
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-shodh-surface';

const MAX_TEXTAREA_HEIGHT = 200;
const MAX_COMPACT_HEIGHT = 120;

export interface AgentComposerHandle {
  focus: () => void;
}

/** An image pasted into the composer: a file the webview exposes, or the system clipboard's bitmap. */
export type PastedImage = { kind: 'file'; file: File } | { kind: 'clipboard' };

interface AgentComposerProps {
  /** Distinguishes the Ask and dock inputs (label/description ids). */
  id: string;
  value: string;
  onChange: (value: string) => void;
  /** Send a new message (idle). */
  onSubmit: () => void;
  /** Redirect the running answer. */
  onSteer: () => void;
  /** Interrupt the running answer. */
  onStop: () => void;
  /**
   * Approve the pending step with Enter on an empty input. Leave unset for
   * destructive steps, which must be approved on the prompt itself.
   */
  onApprove?: () => void;
  /** An answer is running in this conversation. */
  running: boolean;
  /** The running answer accepts steering (it has started). */
  canSteer: boolean;
  /** A step is waiting for approval. */
  approvalPending?: boolean;
  /** Sending is blocked (e.g. an answer is running in another conversation). */
  blockedReason: string | null;
  placeholder: string;
  /** The model chip (Ask only): shows and changes the model the next answer uses. */
  modelChip?: React.ReactNode;
  scopeLabel?: string;
  scopeTitle?: string;
  onOpenLibrary?: () => void;
  /** A control next to the scope chip (e.g. "Search all my library" in a workspace). */
  scopeAction?: React.ReactNode;
  onPickImage?: () => void;
  /** An image (with no text) was pasted; the paste itself is cancelled. Text pastes are untouched. */
  onPasteImage?: (image: PastedImage) => void;
  /** Shown above the input: what goes out with the next question (image text chips). */
  attachments?: React.ReactNode;
  autoFocus?: boolean;
  /** Dense variant for the conversation dock: no chips, smaller type. */
  compact?: boolean;
  /** Placeholder while an answer runs and cannot be steered from here. */
  runningPlaceholder?: string;
}

/**
 * Message input. Idle: Enter sends. While an answer runs: Enter steers it,
 * Esc interrupts it (handled by the hosting view), and with an approval
 * pending an empty Enter approves. Shift+Enter inserts a newline.
 */
export const AgentComposer = forwardRef<AgentComposerHandle, AgentComposerProps>(function AgentComposer(
  {
    id,
    value,
    onChange,
    onSubmit,
    onSteer,
    onStop,
    onApprove,
    running,
    canSteer,
    approvalPending = false,
    blockedReason,
    placeholder,
    modelChip,
    scopeLabel,
    scopeTitle,
    onOpenLibrary,
    scopeAction,
    onPickImage,
    onPasteImage,
    attachments,
    autoFocus = false,
    compact = false,
    runningPlaceholder,
  },
  ref,
) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const valueRef = useRef(value);
  valueRef.current = value;
  const inputId = `${id}-input`;
  const blockedId = `${id}-blocked`;
  const maxHeight = compact ? MAX_COMPACT_HEIGHT : MAX_TEXTAREA_HEIGHT;

  useImperativeHandle(ref, () => ({ focus: () => textareaRef.current?.focus() }), []);

  const getText = useCallback(() => valueRef.current, []);
  const voice = useVoiceInput(getText, onChange);

  // Grow with content up to a cap, then scroll. Where the engine sizes the
  // field itself (CSS field-sizing) nothing is measured per keystroke;
  // measuring (height auto, then scrollHeight) forces a layout of the whole
  // page, which made typing lag in long conversations.
  useLayoutEffect(() => {
    if (NATIVE_FIELD_SIZING) return;
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, maxHeight)}px`;
  }, [value, maxHeight]);

  const hasText = value.trim().length > 0;
  const canSend = hasText && !running && blockedReason === null;
  const canSteerNow = hasText && running && canSteer;

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key !== 'Enter' || e.shiftKey || e.nativeEvent.isComposing) return;
    e.preventDefault();
    if (running) {
      if (canSteerNow) onSteer();
      else if (!hasText && approvalPending && onApprove) onApprove();
    } else if (canSend) {
      onSubmit();
    }
  };

  // Decided while the event runs, so the default paste can still be cancelled.
  const handlePaste = (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    if (!onPasteImage) return;
    const files = Array.from(e.clipboardData.files);
    const decision = pasteDecision(e.clipboardData.getData('text/plain'), files.map(f => f.type));
    if (decision.kind === 'text') return;
    e.preventDefault();
    onPasteImage(decision.kind === 'file' ? { kind: 'file', file: files[decision.index] } : { kind: 'clipboard' });
  };

  const effectivePlaceholder = running
    ? approvalPending
      ? onApprove
        ? 'Enter to approve · Esc to deny · or type to steer…'
        : 'Approve or deny above · Esc to deny…'
      : !canSteer && runningPlaceholder
        ? runningPlaceholder
        : 'Steer the agent…'
    : placeholder;

  const iconButton = cn(
    'w-[34px] h-[34px] shrink-0 inline-flex items-center justify-center rounded-[10px] text-shodh-text-muted hover:bg-shodh-raised hover:text-shodh-text transition-colors duration-micro',
    FOCUS_RING,
  );
  const chip = cn(
    'inline-flex items-center gap-[7px] h-[30px] px-2.5 rounded-full bg-shodh-raised-2 text-[12.5px] text-shodh-text-secondary hover:bg-shodh-pressed hover:text-shodh-text transition-colors duration-micro min-w-0',
    FOCUS_RING,
  );
  const roundButton = cn(
    'shrink-0 rounded-full inline-flex items-center justify-center bg-shodh-text text-shodh-ground hover:opacity-90 transition-opacity duration-micro disabled:bg-shodh-raised-2 disabled:text-shodh-text-faint disabled:cursor-not-allowed',
    compact ? 'w-8 h-8' : 'w-9 h-9',
    FOCUS_RING,
  );

  return (
    <div
      className={cn(
        'border border-shodh-border-strong bg-shodh-surface has-[textarea:focus-visible]:border-shodh-text-faint has-[textarea:focus-visible]:ring-1 has-[textarea:focus-visible]:ring-ring/60',
        compact ? 'rounded-[14px]' : 'rounded-[22px] shadow-[0_12px_40px_rgba(0,0,0,0.35)]',
      )}
    >
      {attachments}
      <label htmlFor={inputId} className="sr-only">
        {running ? 'Steer the running answer' : 'Message Shodh'}
      </label>
      <textarea
        id={inputId}
        ref={textareaRef}
        rows={compact ? 1 : 2}
        value={value}
        onChange={e => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        placeholder={effectivePlaceholder}
        autoFocus={autoFocus}
        aria-describedby={blockedReason ? blockedId : undefined}
        className={cn(
          'block w-full resize-none [field-sizing:content] border-0 bg-transparent text-shodh-text placeholder:text-shodh-text-faint outline-none focus:outline-none scrollbar-thin',
          compact ? 'px-3 pt-2.5 pb-0.5 text-[13.5px] leading-[1.45]' : 'px-[18px] pt-4 pb-1 text-[15px] leading-[1.5]',
        )}
        style={NATIVE_FIELD_SIZING ? { maxHeight, minHeight: compact ? MIN_COMPACT_HEIGHT : MIN_TEXTAREA_HEIGHT } : { maxHeight }}
      />
      <div className={cn('flex flex-wrap items-center gap-x-1.5 gap-y-2 min-w-0', compact ? 'px-2 pt-1 pb-2' : 'px-2.5 pt-1.5 pb-2.5')}>
        {!compact && onPickImage && (
          <button
            type="button"
            onClick={onPickImage}
            aria-label="Add an image: its text is attached to your next question"
            title="Add an image (its text is attached to your next question)"
            className={iconButton}
          >
            <ImagePlus className="w-[17px] h-[17px]" aria-hidden="true" />
          </button>
        )}
        {!compact && voice.supported && (
          <button
            type="button"
            onClick={voice.toggle}
            aria-pressed={voice.listening}
            aria-label={voice.listening ? 'Stop dictation' : 'Dictate'}
            title={voice.listening ? 'Stop dictation' : 'Dictate'}
            className={cn(iconButton, voice.listening && 'text-shodh-error bg-shodh-raised')}
          >
            {voice.listening ? <MicOff className="w-[17px] h-[17px]" aria-hidden="true" /> : <Mic className="w-[17px] h-[17px]" aria-hidden="true" />}
          </button>
        )}
        {!compact && modelChip}
        {!compact && scopeLabel && onOpenLibrary && (
          <button
            type="button"
            onClick={onOpenLibrary}
            className={chip}
            title={scopeTitle}
            aria-label={scopeTitle ? `${scopeLabel}. ${scopeTitle}` : scopeLabel}
          >
            <Folder className="w-3 h-3 shrink-0" strokeWidth={2.2} aria-hidden="true" />
            <span className="truncate max-w-[200px]">{scopeLabel}</span>
          </button>
        )}
        {!compact && scopeAction}
        <div className="ml-auto flex items-center gap-1.5">
          {running && hasText && (
            <button
              type="button"
              onClick={onSteer}
              disabled={!canSteerNow}
              aria-label="Steer the answer (Enter)"
              title="Steer (Enter)"
              className={roundButton}
            >
              <CornerDownRight className="w-4 h-4" strokeWidth={2.4} aria-hidden="true" />
            </button>
          )}
          {running ? (
            <button type="button" onClick={onStop} aria-label="Interrupt the answer (Esc)" title="Interrupt (Esc)" className={roundButton}>
              <Square className="w-3.5 h-3.5" fill="currentColor" aria-hidden="true" />
            </button>
          ) : (
            <button type="button" onClick={onSubmit} disabled={!canSend} aria-label="Send" title="Send (Enter)" className={roundButton}>
              <ArrowUp className="w-4 h-4" strokeWidth={2.6} aria-hidden="true" />
            </button>
          )}
        </div>
      </div>
      {blockedReason && (
        <p id={blockedId} className={cn('-mt-1 text-[12px] text-shodh-text-muted', compact ? 'px-3 pb-2' : 'px-[18px] pb-3')}>
          {blockedReason}
        </p>
      )}
    </div>
  );
});

export default AgentComposer;

//! Configure the active LLM from the environment at startup.
//!
//! Opt-in: nothing is configured unless `SHODH_LLM_PROVIDER` is set, so the app
//! never starts sending questions to a cloud provider by surprise. This also lets
//! IT pre-configure an approved provider and model for managed installs.
//!
//! - `SHODH_LLM_PROVIDER`: openrouter | anthropic | openai | google | grok | ollama
//! - `SHODH_LLM_MODEL`: provider model id (optional; a sensible default is used)
//! - API key: the provider's conventional variable, e.g. `OPENROUTER_API_KEY`

use shodh_rag::harness::model_catalog::ModelRef;
use shodh_rag::llm::{ApiProvider, LLMManager, LLMMode};

use crate::llm_commands::LLMState;

pub const PROVIDER_VAR: &str = "SHODH_LLM_PROVIDER";
pub const MODEL_VAR: &str = "SHODH_LLM_MODEL";

#[derive(Debug, Clone)]
struct ProviderSpec {
    provider: ApiProvider,
    label: &'static str,
    key_vars: &'static [&'static str],
    default_model: &'static str,
}

fn spec_for(name: &str) -> Option<ProviderSpec> {
    let spec = match name.trim().to_ascii_lowercase().as_str() {
        "openrouter" => ProviderSpec {
            provider: ApiProvider::OpenRouter,
            label: "OpenRouter",
            key_vars: &["OPENROUTER_API_KEY"],
            default_model: "anthropic/claude-haiku-4.5",
        },
        "anthropic" => ProviderSpec {
            provider: ApiProvider::Anthropic,
            label: "Anthropic",
            key_vars: &["ANTHROPIC_API_KEY"],
            default_model: "claude-haiku-4-5",
        },
        "openai" => ProviderSpec {
            provider: ApiProvider::OpenAI,
            label: "OpenAI",
            key_vars: &["OPENAI_API_KEY"],
            default_model: "gpt-5-mini",
        },
        "google" | "gemini" => ProviderSpec {
            provider: ApiProvider::Google,
            label: "Google",
            key_vars: &["GEMINI_API_KEY", "GOOGLE_API_KEY"],
            default_model: "gemini-2.5-flash",
        },
        "grok" | "xai" => ProviderSpec {
            provider: ApiProvider::Grok,
            label: "xAI",
            key_vars: &["XAI_API_KEY"],
            default_model: "grok-4",
        },
        "ollama" => ProviderSpec {
            provider: ApiProvider::Ollama,
            label: "Ollama",
            key_vars: &[],
            default_model: "qwen3:4b",
        },
        _ => return None,
    };
    Some(spec)
}

/// Resolved settings, separated from activation so the environment parsing is testable.
#[derive(Debug, Clone)]
struct EnvSelection {
    spec: ProviderSpec,
    api_key: String,
    model: String,
}

fn non_empty(value: Option<String>) -> Option<String> {
    value
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
}

fn resolve(get: impl Fn(&str) -> Option<String>) -> Result<Option<EnvSelection>, String> {
    let Some(name) = non_empty(get(PROVIDER_VAR)) else {
        return Ok(None);
    };
    let spec = spec_for(&name).ok_or_else(|| {
        format!("{PROVIDER_VAR}={name} is not supported (use openrouter, anthropic, openai, google, grok or ollama)")
    })?;
    let api_key = if spec.key_vars.is_empty() {
        "ollama".to_string()
    } else {
        spec.key_vars
            .iter()
            .find_map(|var| non_empty(get(var)))
            .ok_or_else(|| {
                format!(
                    "{PROVIDER_VAR}={name} is set but no API key was found in {}",
                    spec.key_vars.join(" or ")
                )
            })?
    };
    let model = non_empty(get(MODEL_VAR)).unwrap_or_else(|| spec.default_model.to_string());
    Ok(Some(EnvSelection {
        spec,
        api_key,
        model,
    }))
}

/// What the environment configured.
#[derive(Debug, Clone)]
pub struct EnvironmentModel {
    /// "provider · model", for the log.
    pub description: String,
    /// The model as the picker names it (`None` for an id the picker cannot hold).
    pub model: Option<ModelRef>,
}

/// Activate the provider named in the environment. `None` when opted out.
pub async fn configure_from_environment(
    state: &LLMState,
) -> Result<Option<EnvironmentModel>, String> {
    let Some(selection) = resolve(|var| std::env::var(var).ok())? else {
        return Ok(None);
    };

    {
        let mut keys = state.api_keys.lock().unwrap_or_else(|e| e.into_inner());
        let key = Some(selection.api_key.clone());
        let id = match selection.spec.provider {
            ApiProvider::OpenRouter => Some("openrouter"),
            ApiProvider::Anthropic => Some("anthropic"),
            ApiProvider::OpenAI => Some("openai"),
            ApiProvider::Google => Some("google"),
            ApiProvider::Grok => Some("grok"),
            _ => None,
        };
        if let Some(id) = id {
            keys.set(id, key);
        }
    }

    let config = {
        let mut config = state.config.lock().unwrap_or_else(|e| e.into_inner());
        config.mode = LLMMode::External {
            provider: selection.spec.provider.clone(),
            api_key: selection.api_key,
            model: selection.model.clone(),
        };
        config.clone()
    };

    let mut manager = LLMManager::new(config);
    manager.initialize().await.map_err(|e| {
        format!(
            "failed to initialize {} model {}: {e}",
            selection.spec.label, selection.model
        )
    })?;
    *state.manager.write().await = Some(manager);

    Ok(Some(EnvironmentModel {
        description: format!("{} · {}", selection.spec.label, selection.model),
        model: crate::model_picker_commands::model_ref_for(
            &selection.spec.provider,
            &selection.model,
        ),
    }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn env(pairs: &[(&str, &str)]) -> impl Fn(&str) -> Option<String> {
        let map: HashMap<String, String> = pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        move |k| map.get(k).cloned()
    }

    #[test]
    fn opted_out_when_provider_unset_or_blank() {
        assert!(resolve(env(&[("OPENROUTER_API_KEY", "k")]))
            .unwrap()
            .is_none());
        assert!(resolve(env(&[(PROVIDER_VAR, "  ")])).unwrap().is_none());
    }

    #[test]
    fn openrouter_with_model_override() {
        let sel = resolve(env(&[
            (PROVIDER_VAR, "OpenRouter"),
            ("OPENROUTER_API_KEY", " sk-or-test "),
            (MODEL_VAR, "stealth/space-bunny-alpha"),
        ]))
        .unwrap()
        .unwrap();
        assert!(matches!(sel.spec.provider, ApiProvider::OpenRouter));
        assert_eq!(sel.api_key, "sk-or-test");
        assert_eq!(sel.model, "stealth/space-bunny-alpha");
    }

    #[test]
    fn default_model_when_unset() {
        let sel = resolve(env(&[
            (PROVIDER_VAR, "openrouter"),
            ("OPENROUTER_API_KEY", "k"),
        ]))
        .unwrap()
        .unwrap();
        assert_eq!(sel.model, "anthropic/claude-haiku-4.5");
    }

    #[test]
    fn missing_key_and_unknown_provider_are_errors() {
        let err = resolve(env(&[(PROVIDER_VAR, "openrouter")])).unwrap_err();
        assert!(err.contains("OPENROUTER_API_KEY"));
        assert!(resolve(env(&[(PROVIDER_VAR, "acme-ai")])).is_err());
    }

    #[test]
    fn google_accepts_either_key_variable_and_ollama_needs_none() {
        let sel = resolve(env(&[(PROVIDER_VAR, "gemini"), ("GOOGLE_API_KEY", "g")]))
            .unwrap()
            .unwrap();
        assert_eq!(sel.api_key, "g");
        assert!(resolve(env(&[(PROVIDER_VAR, "ollama")])).unwrap().is_some());
    }
}

/** Emitted by the backend (`table_model_commands.rs`) at most once per run. */
export const TABLE_MODEL_SUGGESTED_EVENT = 'table-model-suggested';
/** Set once the suggestion was shown, so it is not repeated in later runs. */
export const PROMPT_SHOWN_KEY = 'shodh.tableModelPromptShown';

/**
 * Whether the table model offer should be shown now, recording that it was:
 * true the first time only. Storage that cannot be read or written never blocks
 * the offer (it may then show again in a later run).
 */
export function claimTableModelOffer(storage: Pick<Storage, 'getItem' | 'setItem'> | null): boolean {
  let shown = false;
  try {
    shown = storage?.getItem(PROMPT_SHOWN_KEY) === '1';
  } catch {
    shown = false;
  }
  if (shown) return false;
  try {
    storage?.setItem(PROMPT_SHOWN_KEY, '1');
  } catch {
    // Without storage the offer may repeat in a later run; nothing breaks.
  }
  return true;
}

/**
 * Search model setup: wire types for `search_models_status` /
 * `install_search_models` and pure helpers for the setup card. No React and
 * type-only imports, so it is unit-tested directly with Node
 * (`app/tests/searchModels.test.ts`).
 */

export const SEARCH_MODELS_PROGRESS_EVENT = 'search-models-progress';
export const SEARCH_MODELS_READY_EVENT = 'search-models-ready';

/** Error code at the start of a failure caused by missing models. */
export const SEARCH_MODELS_MISSING_CODE = 'search_models_missing';
/** Error code when another install is already running. */
export const INSTALL_IN_PROGRESS_CODE = 'install_in_progress';

export type ArtifactState = 'missing' | 'partial' | 'unverified' | 'verified' | 'corrupt';

export interface ArtifactStatus {
  name: string;
  relativePath: string;
  size: number;
  sha256: string;
  state: ArtifactState;
  presentBytes: number;
}

export interface SearchModelsStatus {
  ready: boolean;
  installing: boolean;
  modelDir: string;
  totalBytes: number;
  artifacts: ArtifactStatus[];
}

export type InstallPhase = 'checking' | 'downloading' | 'verifying' | 'verified';

export interface InstallProgress {
  artifact: string;
  phase: InstallPhase;
  artifactBytes: number;
  artifactTotal: number;
  overallBytes: number;
  overallTotal: number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

export function isInstallProgress(value: unknown): value is InstallProgress {
  return (
    isRecord(value) &&
    typeof value.artifact === 'string' &&
    typeof value.phase === 'string' &&
    typeof value.overallBytes === 'number' &&
    typeof value.overallTotal === 'number'
  );
}

export function isSearchModelsStatus(value: unknown): value is SearchModelsStatus {
  return isRecord(value) && typeof value.ready === 'boolean' && Array.isArray(value.artifacts);
}

/** What the setup card should offer for a status. */
export interface SetupSummary {
  /** Search cannot run until the models are installed. */
  needed: boolean;
  /** A previous download was interrupted and will resume. */
  resumable: boolean;
  /** Some file on disk failed verification and will be replaced. */
  hasCorrupt: boolean;
  /** Bytes still to download (approximate for partial files). */
  remainingBytes: number;
  totalBytes: number;
}

export function summarizeSetup(status: SearchModelsStatus): SetupSummary {
  let remaining = 0;
  let resumable = false;
  let hasCorrupt = false;
  for (const a of status.artifacts) {
    if (a.state === 'verified') continue;
    if (a.state === 'partial') {
      resumable = true;
      remaining += Math.max(0, a.size - a.presentBytes);
    } else {
      if (a.state === 'corrupt') hasCorrupt = true;
      remaining += a.size;
    }
  }
  return {
    needed: !status.ready,
    resumable,
    hasCorrupt,
    remainingBytes: remaining,
    totalBytes: status.totalBytes,
  };
}

/** Fraction (0–1) of the whole install, or null before the first event. */
export function installFraction(progress: InstallProgress | null): number | null {
  if (!progress || progress.overallTotal <= 0) return null;
  return Math.min(1, Math.max(0, progress.overallBytes / progress.overallTotal));
}

/** "555.0 MB" style size. */
export function formatMegabytes(bytes: number): string {
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Status line for a running install. */
export function describeProgress(progress: InstallProgress | null): string {
  if (!progress) return 'Connecting…';
  switch (progress.phase) {
    case 'checking':
      return `Checking ${progress.artifact}…`;
    case 'downloading':
      return `Downloading ${progress.artifact} · ${formatMegabytes(progress.overallBytes)} of ${formatMegabytes(progress.overallTotal)}`;
    case 'verifying':
      return `Verifying ${progress.artifact} (SHA-256)…`;
    case 'verified':
      return `${progress.artifact} verified · ${formatMegabytes(progress.overallBytes)} of ${formatMegabytes(progress.overallTotal)}`;
  }
}

/** The message of a command error, without its machine-readable code prefix. */
export function errorMessage(error: unknown): string {
  const raw = error instanceof Error ? error.message : String(error);
  for (const code of [SEARCH_MODELS_MISSING_CODE, INSTALL_IN_PROGRESS_CODE]) {
    if (raw.startsWith(`${code}: `)) {
      const rest = raw.slice(code.length + 2);
      return rest.charAt(0).toUpperCase() + rest.slice(1);
    }
  }
  return raw;
}

/** Folder of the scan reader's files (the PP-OCRv6 model) under the model folder. */
export const SCAN_READER_DIR = 'pp-ocrv6/';

/** The scan reader as the search model status reports it. */
export interface ScanReaderSummary {
  /** Every file of the scan reader is on disk. */
  installed: boolean;
  /** A download of it was interrupted and resumes. */
  resumable: boolean;
  totalBytes: number;
  /** Bytes still to download. */
  remainingBytes: number;
}

/**
 * Whether the scan reader is installed, from the status's model files. Null when
 * the status lists none of its files (a build that did not install it).
 */
export function scanReaderSummary(status: SearchModelsStatus): ScanReaderSummary | null {
  const files = status.artifacts.filter(a => a.relativePath.replace(/\\/g, '/').startsWith(SCAN_READER_DIR));
  if (files.length === 0) return null;
  let remaining = 0;
  let resumable = false;
  let total = 0;
  for (const file of files) {
    total += file.size;
    // Present but not hashed yet (status checks skip hashing once search is ready).
    if (file.state === 'verified' || file.state === 'unverified') continue;
    if (file.state === 'partial') {
      resumable = true;
      remaining += Math.max(0, file.size - file.presentBytes);
    } else {
      remaining += file.size;
    }
  }
  return {
    installed: files.every(f => f.state === 'verified' || f.state === 'unverified'),
    resumable,
    totalBytes: total,
    remainingBytes: remaining,
  };
}

import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { listen } from '@tauri-apps/api/event';
import type { UnlistenFn } from '@tauri-apps/api/event';
import {
  INSTALL_IN_PROGRESS_CODE,
  SEARCH_MODELS_PROGRESS_EVENT,
  SEARCH_MODELS_READY_EVENT,
  errorMessage,
  isInstallProgress,
  isSearchModelsStatus,
} from './searchModels';
import type { InstallProgress, SearchModelsStatus } from './searchModels';

interface SearchModelsContextValue {
  /** Latest status, or null until the first check finishes. */
  status: SearchModelsStatus | null;
  /** The status check itself failed. */
  statusError: string | null;
  installing: boolean;
  progress: InstallProgress | null;
  installError: string | null;
  /** Status returned by an install that finished in this session. */
  installed: SearchModelsStatus | null;
  install: () => Promise<void>;
  refresh: () => Promise<void>;
  dismissInstalled: () => void;
}

const SearchModelsContext = createContext<SearchModelsContextValue | null>(null);

/**
 * One shared view of the search model setup, so every setup card (Ask,
 * Library) shows the same install and only one install runs at a time.
 */
export function SearchModelsProvider({ children }: { children: React.ReactNode }) {
  const [status, setStatus] = useState<SearchModelsStatus | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);
  const [installing, setInstalling] = useState(false);
  const [progress, setProgress] = useState<InstallProgress | null>(null);
  const [installError, setInstallError] = useState<string | null>(null);
  const [installed, setInstalled] = useState<SearchModelsStatus | null>(null);
  const installingRef = useRef(false);

  const refresh = useCallback(async () => {
    try {
      const next = await invoke<unknown>('search_models_status');
      if (!isSearchModelsStatus(next)) throw new Error('Unexpected search setup status');
      setStatus(next);
      setStatusError(null);
      // An install started earlier (e.g. before a reload) is still running.
      if (next.installing && !installingRef.current) setInstalling(true);
      if (!next.installing && !installingRef.current) setInstalling(false);
    } catch (error) {
      setStatusError(errorMessage(error));
    }
  }, []);

  // Subscribe to progress before any install can start.
  useEffect(() => {
    let disposed = false;
    const unlisteners: UnlistenFn[] = [];
    const subscribe = (event: string, handler: (payload: unknown) => void) => {
      listen<unknown>(event, e => handler(e.payload))
        .then(fn => {
          if (disposed) fn();
          else unlisteners.push(fn);
        })
        .catch(err => console.error(`Failed to listen for ${event}:`, err));
    };
    subscribe(SEARCH_MODELS_PROGRESS_EVENT, payload => {
      if (isInstallProgress(payload)) setProgress(payload);
    });
    subscribe(SEARCH_MODELS_READY_EVENT, () => {
      void refresh();
    });
    void refresh();
    return () => {
      disposed = true;
      unlisteners.forEach(fn => fn());
    };
  }, [refresh]);

  // An install this view did not start (another window, or before a reload)
  // reports success through the ready event; poll so a failure also ends it.
  useEffect(() => {
    if (!installing || installingRef.current) return;
    const timer = window.setInterval(() => void refresh(), 3000);
    return () => window.clearInterval(timer);
  }, [installing, refresh]);

  const install = useCallback(async () => {
    if (installingRef.current) return;
    installingRef.current = true;
    setInstalling(true);
    setInstallError(null);
    setProgress(null);
    try {
      const result = await invoke<unknown>('install_search_models');
      if (!isSearchModelsStatus(result)) throw new Error('Unexpected search setup result');
      setStatus(result);
      setInstalled(result);
    } catch (error) {
      const raw = error instanceof Error ? error.message : String(error);
      if (!raw.startsWith(INSTALL_IN_PROGRESS_CODE)) setInstallError(errorMessage(error));
      await refresh();
    } finally {
      installingRef.current = false;
      setInstalling(false);
    }
  }, [refresh]);

  const dismissInstalled = useCallback(() => setInstalled(null), []);

  const value = useMemo<SearchModelsContextValue>(
    () => ({ status, statusError, installing, progress, installError, installed, install, refresh, dismissInstalled }),
    [status, statusError, installing, progress, installError, installed, install, refresh, dismissInstalled],
  );

  return <SearchModelsContext.Provider value={value}>{children}</SearchModelsContext.Provider>;
}

export function useSearchModels(): SearchModelsContextValue {
  const context = useContext(SearchModelsContext);
  if (!context) throw new Error('useSearchModels must be used within a SearchModelsProvider');
  return context;
}

import React, { useEffect } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { listen } from '@tauri-apps/api/event';
import { Download, Table2 } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '../../lib/utils';
import { notify } from '../../lib/notify';
import { claimTableModelOffer, TABLE_MODEL_SUGGESTED_EVENT } from './tableModelOffer';

const TOAST_ID = 'table-model-suggested';

const FOCUS_RING =
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-shodh-surface';
const ACTION = cn(
  'h-7 px-2.5 inline-flex items-center gap-1 rounded-md text-[12px] font-medium transition-colors duration-micro',
  FOCUS_RING,
);

function browserStorage(): Storage | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function install() {
  toast.dismiss(TOAST_ID);
  notify.info('Installing the table model', { description: 'Tables are re-read in the background when it is ready.' });
  invoke('install_table_model')
    .then(() => notify.success('Table model installed', { description: 'Indexed PDFs with tables are being refined.' }))
    .catch(err => notify.error('The table model could not be installed', { description: errorText(err) }));
}

function SuggestionToast() {
  return (
    <div
      role="status"
      aria-labelledby="table-model-suggested-title"
      aria-describedby="table-model-suggested-text"
      className="w-[356px] max-w-full flex flex-col gap-2 p-3 rounded-[10px] border border-shodh-border-strong bg-shodh-surface text-shodh-text shadow-[0_8px_24px_rgba(0,0,0,0.3)]"
    >
      <div className="flex items-start gap-2">
        <Table2 className="w-4 h-4 mt-0.5 shrink-0 text-shodh-accent-text" aria-hidden="true" />
        <div className="min-w-0 flex flex-col">
          <span id="table-model-suggested-title" className="text-[13px] font-medium">
            Install the table model for better tables (212 MB)
          </span>
          <span id="table-model-suggested-text" className="text-[11.5px] text-shodh-text-muted">
            Some of your PDFs have tables. Without the model they are read with layout rules only, and rows or cells
            can be missed. You can also install it later in Settings → Search.
          </span>
        </div>
      </div>
      <div className="flex items-center gap-1.5 justify-end">
        <button
          type="button"
          className={cn(ACTION, 'text-shodh-text-muted hover:bg-shodh-raised hover:text-shodh-text')}
          onClick={() => toast.dismiss(TOAST_ID)}
        >
          Not now
        </button>
