test('a draft is kept per conversation and outlives the component that typed it', () => {
  const drafts = new DraftStore();
  drafts.set('c1', 'What does figure 3');
  drafts.set('c2', 'Compare');
  assert.equal(drafts.get('c1'), 'What does figure 3');
  assert.equal(drafts.get('c2'), 'Compare');
  assert.equal(drafts.get('c3'), '');
  assert.equal(drafts.get(null), '');
});

test('appending a snippet builds on the current text; clearing forgets it', () => {
  const drafts = new DraftStore();
  drafts.set('c1', 'Explain');
  drafts.update('c1', current => `${current} this`);
  assert.equal(drafts.get('c1'), 'Explain this');
  drafts.set('c1', '');
  assert.equal(drafts.get('c1'), '');
});

test('subscribers hear real changes only, and stop hearing once unsubscribed', () => {
  const drafts = new DraftStore();
  let calls = 0;
  const stop = drafts.subscribe(() => { calls += 1; });
  drafts.set('c1', 'a');
  drafts.set('c1', 'a');
  drafts.update('c1', t => `${t}b`);
  assert.equal(calls, 2);
  stop();
  drafts.set('c1', 'abc');
  assert.equal(calls, 2);
});

test('Ask and the dock read one draft store and one send-options function', () => {
  for (const file of ['../src/features/ask/AskView.tsx', '../src/components/shell/ConversationDock.tsx']) {
    const source = readFileSync(new URL(file, import.meta.url), 'utf8');
    assert.match(source, /useDraft\(session\.activeConversationId\)/, file);
    assert.match(source, /useSendOptions\(sources\)/, file);
    assert.doesNotMatch(source, /useState\(''\)/, file);
  }
});

const src = (id: string, selected: boolean) => ({ id, name: `Folder ${id}`, selected });

test('only some sources included: answers search just those', () => {
  const options = sendOptionsFor([src('a', true), src('b', false), src('c', true)]);
  assert.deepEqual(options, { spaceId: 'a', spaceName: 'Folder a', sourceIds: ['a', 'c'] });
});

test('every source or none included: answers search everything', () => {
  assert.deepEqual(sendOptionsFor([src('a', true), src('b', true)]).sourceIds, []);
  assert.deepEqual(sendOptionsFor([src('a', false)]), { spaceId: null, spaceName: null, sourceIds: [] });
  assert.deepEqual(sendOptionsFor([]).sourceIds, []);
});

test('equal options share a key, different choices do not', () => {
  const one = sendOptionsFor([src('a', true), src('b', false)]);
  const same = sendOptionsFor([{ ...src('a', true) }, { ...src('b', false) }]);
  const other = sendOptionsFor([src('a', false), src('b', true)]);
  assert.equal(sendOptionsKey(one), sendOptionsKey(same));
  assert.notEqual(sendOptionsKey(one), sendOptionsKey(other));
});

import { parsePageSpan, samePathSpelling } from '../ask/searchResults';
import type { SearchHit } from '../ask/types';
import type { Passage } from './reducer';

/**
 * Passages of a run as citation targets. `number` is the passage's run-wide
 * `n`, which is exactly what the model writes as `[n]`. Web sources carry
 * their address in `url`, which is how the UI tells them apart from
 * document citations.
 */
export function passageHits(passages: readonly Passage[]): SearchHit[] {
  return passages.map(p => ({
    number: p.n,
    sourceFile: p.path,
    fileName: p.file,
    title: p.heading ? `${p.file} · ${p.heading}` : p.file,
    text: p.text,
    snippet: p.text.slice(0, 200),
    score: p.score,
    page: p.web ? null : parsePageSpan(p.page),
    lineRange: null,
    url: p.web ? p.path : null,
    section: p.web ? null : (p.section ?? null),
    regions: p.web ? null : (p.regions ?? null),
    ...(!p.web && samePathSpelling(p.path, p.displayPath) ? { displayPath: p.displayPath } : {}),
  }));
}

//! The citation graph of the user's papers.
//!
//! Each library PDF is scanned for its own identity (title, DOI or arXiv id) and its
//! bibliography, one parsed reference per entry ([`reference`], [`segment`],
//! [`identity`], [`scan`]). When the user's privacy policy allows the web, papers are
//! matched to OpenAlex works by identifier, or by a strict title match for references
//! without one ([`resolve`]); only bibliographic identifiers and reference titles are sent.
//! The graph is assembled deterministically ([`build`]) and stored as research-pack
//! statements: Paper nodes (library papers flagged `inLibrary`) with `cites`,
//! `authoredBy`, `publishedIn`, `usesMethod` and `evaluatedOn`, Author and Venue nodes, and
//! Method nodes with `proposedIn` ([`service`]). Methods and datasets come only from Result
//! statements and deterministic heading/caption rules; no entity model is involved.
//!
//! [`graph`] serves the snapshot: neighbours, citers, shared references, lineage paths,
//! filters, and personalized PageRank, which ranks library files as a third list for
//! document search ([`crate::search::graph_fusion`]). [`views`] shapes it for the pages,
//! the graph view and the agent tools.
