//! Text normalisation shared by the reference parser, local paper identification and the
//! matching rules: ligatures, line-break hyphenation, diacritics and title comparison.

/// Replaces typographic ligatures and look-alike punctuation that PDF text extraction
/// produces (`ﬁ`, `ﬂ`, curly quotes, non-breaking spaces) with plain characters.
pub fn expand_ligatures(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '\u{FB00}' => out.push_str("ff"),
            '\u{FB01}' => out.push_str("fi"),
            '\u{FB02}' => out.push_str("fl"),
            '\u{FB03}' => out.push_str("ffi"),
            '\u{FB04}' => out.push_str("ffl"),
            '\u{FB05}' | '\u{FB06}' => out.push_str("st"),
            '\u{00A0}' | '\u{2002}' | '\u{2003}' | '\u{2009}' | '\u{202F}' => out.push(' '),
            // Soft hyphens, and spacing diacritics that PDF extraction separates from
            // their letter (`Re ´`, `Jorg ¨`).
            '\u{00AD}' | '\u{00B4}' | '\u{00A8}' | '\u{02DC}' | '\u{02C6}' | '\u{00B8}'
            | '\u{02DA}' | '\u{02C7}' | '\u{02D8}' | '\u{02DD}' => {}
            '\u{2010}' | '\u{2011}' => out.push('-'),
            other => out.push(other),
        }
    }
    out
}

/// One line of text from a block that may span several lines: ligatures expanded, a word
/// broken across lines by a hyphen joined (`trans-\nformers` → `transformers`, while
/// `Kolmogorov-\nArnold` keeps its hyphen), and all whitespace collapsed to single spaces.
pub fn clean_block_text(text: &str) -> String {
    let text = expand_ligatures(text);
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '-' {
            // A hyphen at a line end: look at the letters around the break.
            let mut j = i + 1;
            let mut newline = false;
            while j < chars.len() && chars[j].is_whitespace() {
                newline |= chars[j] == '\n' || chars[j] == '\r';
                j += 1;
            }
            if newline {
                let before = i.checked_sub(1).map(|k| chars[k]);
                let after = chars.get(j).copied();
                let joins = before.is_some_and(|b| b.is_lowercase())
                    && after.is_some_and(|a| a.is_lowercase());
                if !joins {
                    out.push('-');
                }
                i = j;
                continue;
            }
        }
        if c.is_whitespace() {
            if !out.ends_with(' ') && !out.is_empty() {
                out.push(' ');
            }
        } else {
            out.push(c);
        }
        i += 1;
    }
    out.trim().to_string()
}

/// The ASCII form of a Latin letter with diacritics (`ü` → `u`, `ł` → `l`, `ß` → `ss`);
/// other characters are returned unchanged.
fn fold_char(c: char, out: &mut String) {
    let folded: &str = match c {
        'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' | 'ă' | 'ą' => "a",
        'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' | 'Ā' | 'Ă' | 'Ą' => "A",
        'æ' => "ae",
        'Æ' => "AE",
        'ç' | 'ć' | 'č' | 'ĉ' | 'ċ' => "c",
        'Ç' | 'Ć' | 'Č' | 'Ĉ' | 'Ċ' => "C",
        'ď' | 'đ' | 'ð' => "d",
        'Ď' | 'Đ' | 'Ð' => "D",
        'è' | 'é' | 'ê' | 'ë' | 'ē' | 'ĕ' | 'ė' | 'ę' | 'ě' => "e",
        'È' | 'É' | 'Ê' | 'Ë' | 'Ē' | 'Ĕ' | 'Ė' | 'Ę' | 'Ě' => "E",
        'ğ' | 'ĝ' | 'ġ' | 'ģ' => "g",
        'Ğ' | 'Ĝ' | 'Ġ' | 'Ģ' => "G",
        'ì' | 'í' | 'î' | 'ï' | 'ī' | 'ĭ' | 'į' | 'ı' => "i",
        'Ì' | 'Í' | 'Î' | 'Ï' | 'Ī' | 'Ĭ' | 'Į' | 'İ' => "I",
        'ķ' => "k",
        'Ķ' => "K",
        'ł' | 'ľ' | 'ĺ' | 'ļ' => "l",
        'Ł' | 'Ľ' | 'Ĺ' | 'Ļ' => "L",
        'ñ' | 'ń' | 'ň' | 'ņ' => "n",
        'Ñ' | 'Ń' | 'Ň' | 'Ņ' => "N",
        'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' | 'ŏ' | 'ő' => "o",
        'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' | 'Ō' | 'Ŏ' | 'Ő' => "O",
        'œ' => "oe",
        'Œ' => "OE",
        'ŕ' | 'ř' | 'ŗ' => "r",
        'Ŕ' | 'Ř' | 'Ŗ' => "R",
        'ś' | 'š' | 'ş' | 'ŝ' | 'ș' => "s",
        'Ś' | 'Š' | 'Ş' | 'Ŝ' | 'Ș' => "S",
        'ß' => "ss",
        'ť' | 'ţ' | 'ț' => "t",
        'Ť' | 'Ţ' | 'Ț' => "T",
        'ù' | 'ú' | 'û' | 'ü' | 'ū' | 'ŭ' | 'ů' | 'ű' | 'ų' => "u",
        'Ù' | 'Ú' | 'Û' | 'Ü' | 'Ū' | 'Ŭ' | 'Ů' | 'Ű' | 'Ų' => "U",
        'ý' | 'ÿ' => "y",
        'Ý' | 'Ÿ' => "Y",
        'ź' | 'ż' | 'ž' => "z",
        'Ź' | 'Ż' | 'Ž' => "Z",
        'þ' => "th",
        'Þ' => "TH",
        other => {
            out.push(other);
            return;
        }
    };
    out.push_str(folded);
}

/// `text` with Latin diacritics removed.
pub fn fold_diacritics(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        fold_char(c, &mut out);
    }
    out
}

/// The comparable form of a title: ligatures expanded, diacritics folded, lower-cased,
/// every run of non-alphanumeric characters turned into one space.
pub fn normalize_title(title: &str) -> String {
    let folded = fold_diacritics(&expand_ligatures(title)).to_lowercase();
    let mut out = String::with_capacity(folded.len());
    for c in folded.chars() {
        if c.is_alphanumeric() {
            out.push(c);
        } else if !out.ends_with(' ') && !out.is_empty() {
            out.push(' ');
        }
    }
    out.trim_end().to_string()
}

/// The comparable form of a surname: diacritics folded, lower-cased, letters only
/// (`Schmidhuber`, `schmidhuber` and `Schmidhüber` agree; so do `O'Neil` and `ONeil`).
pub fn normalize_surname(name: &str) -> String {
    fold_diacritics(&expand_ligatures(name))
        .to_lowercase()
        .chars()
        .filter(|c| c.is_alphabetic())
        .collect()
}

/// Levenshtein distance between two character sequences.
fn levenshtein(a: &[char], b: &[char]) -> usize {
    if a.is_empty() {
        return b.len();
    }
    if b.is_empty() {
        return a.len();
    }
    let mut previous: Vec<usize> = (0..=b.len()).collect();
    let mut current = vec![0usize; b.len() + 1];
    for (i, ca) in a.iter().enumerate() {
        current[0] = i + 1;
        for (j, cb) in b.iter().enumerate() {
            let substitution = previous[j] + usize::from(ca != cb);
            current[j + 1] = substitution.min(previous[j + 1] + 1).min(current[j] + 1);
        }
        std::mem::swap(&mut previous, &mut current);
    }
    previous[b.len()]
}

/// Similarity of two titles in `[0, 1]`: one minus the edit distance of their normalised
/// forms over the longer length. `1.0` means the normalised titles are equal; two empty
/// titles are not similar (`0.0`).
pub fn title_similarity(a: &str, b: &str) -> f64 {
    let a: Vec<char> = normalize_title(a).chars().collect();
    let b: Vec<char> = normalize_title(b).chars().collect();
    let longest = a.len().max(b.len());
    if longest == 0 {
        return 0.0;
    }
    1.0 - levenshtein(&a, &b) as f64 / longest as f64
}

/// Whether a library paper's title (as read from its first page) and another title name
/// the same work: at least 0.9 similar, or the library title is a cut-off start of the
/// other of at least four words (a title set on two lines, of which the parser kept one).
pub fn titles_agree(library_title: &str, other: &str) -> bool {
    if title_similarity(library_title, other) >= 0.9 {
        return true;
    }
    let short = normalize_title(library_title);
    let long = normalize_title(other);
    short.split(' ').count() >= 4 && long.starts_with(&format!("{short} "))
}

/// A short, stable slug of a name or title: normalised words joined by `-`, at most
/// `max_words` words.
pub fn slug(text: &str, max_words: usize) -> String {
    normalize_title(text)
        .split(' ')
        .filter(|w| !w.is_empty())
        .take(max_words)
        .collect::<Vec<_>>()
        .join("-")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn block_text_joins_hyphenated_words_and_keeps_compound_hyphens() {
        assert_eq!(
            clean_block_text("Linear trans-\nformers are secretly ﬁxed\nweight programmers"),
            "Linear transformers are secretly fixed weight programmers"
        );
        assert_eq!(
            clean_block_text("KAN: Kolmogorov-\nArnold networks"),
            "KAN: Kolmogorov-Arnold networks"
        );
        assert_eq!(clean_block_text("  a\u{00A0} b \n\n c "), "a b c");
    }

    #[test]
    fn titles_compare_without_case_punctuation_or_diacritics() {
        assert_eq!(
            normalize_title("Attention Is All You Need!"),
            "attention is all you need"
        );
        assert!(
            (title_similarity(
                "Linear Transformers Are Secretly Fast Weight Programmers",
                "Linear transformers are secretly fast weight programmers."
            ) - 1.0)
                .abs()
                < 1e-9
        );
        let near = title_similarity(
            "Parallelizing linear transformers with the delta rule over sequence length",
            "Parallelizing Linear Transformers with the Delta Rule over Sequence Length",
        );
        assert!(near > 0.99);
        assert!(title_similarity("Gated delta networks", "Gated linear attention") < 0.9);
        assert_eq!(title_similarity("", ""), 0.0);
        assert_eq!(normalize_surname("Schmidhüber"), "schmidhuber");
        assert_eq!(normalize_surname("Łukasz"), "lukasz");
        assert_eq!(slug("Songlin Yang", 4), "songlin-yang");
        assert!(titles_agree(
            "Linear Transformers Are Secretly",
            "Linear transformers are secretly fast weight programmers"
        ));
        assert!(!titles_agree(
            "Linear Transformers",
            "Linear transformers are RNNs"
        ));
    }
}

//! Measures the graph on a real paper folder, optionally with live OpenAlex lookups.
//!
//! `cargo test -p shodh-rag --lib research::citations::corpus_live -- --ignored --nocapture`
//! with `SHODH_RESEARCH_CORPUS` set to a folder of PDFs and `SHODH_GRAPH_DB` to a
//! `shodh.db` path that keeps the OpenAlex cache between runs. Set `SHODH_LIVE_OPENALEX=1`
//! to allow network lookups (through the same paced, cached client the app uses);
//! otherwise only cached answers are read. A folder named `My Papers` and files marked
//! `(annotated)` are skipped. Prints the build report.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use super::resolve::Resolver;
use super::service::{CitationService, GraphSlot};
use crate::embeddings::EmbeddingModel;
use crate::harness::web::SafeClient;
use crate::research::db::ResearchDb;
use crate::research::results::ResultService;
use crate::statements::testing::{t0, FixedEmbedder, TestClock};
use crate::statements::{DynamicsStore, StatementStore};

/// Hashes words into a fixed number of dimensions (no vocabulary limit).
struct HashEmbedder;

const DIM: usize = 64;

impl EmbeddingModel for HashEmbedder {
    fn embed_query(&self, text: &str) -> anyhow::Result<Vec<f32>> {
        self.embed_document(text)
    }
    fn embed_document(&self, text: &str) -> anyhow::Result<Vec<f32>> {
        let mut v = vec![0.0f32; DIM];
        for word in text
            .split(|c: char| !c.is_alphanumeric())
            .filter(|w| !w.is_empty())
        {
            let h = word
                .to_lowercase()
                .bytes()
                .fold(1469598103934665603u64, |h, b| {
                    (h ^ u64::from(b)).wrapping_mul(1099511628211)
                });
            v[(h % DIM as u64) as usize] += 1.0;
        }
        let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
        Ok(v.into_iter().map(|x| x / norm).collect())
    }
    fn dimension(&self) -> usize {
        DIM
    }
}

fn pdfs_under(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();
        if path.is_dir() {
            if name != "My Papers" {
                pdfs_under(&path, out);
            }
        } else if name.to_lowercase().ends_with(".pdf") && !name.contains("(annotated)") {
            out.push(path);
        }
    }
}

#[tokio::test]
#[ignore = "needs SHODH_RESEARCH_CORPUS and SHODH_GRAPH_DB"]
async fn measure_the_graph_of_a_corpus() {
    let (Ok(corpus), Ok(db_path)) = (
        std::env::var("SHODH_RESEARCH_CORPUS"),
        std::env::var("SHODH_GRAPH_DB"),
    ) else {
        return;
    };
    let dir = tempfile::tempdir().unwrap();
    let ontology = Arc::new(shodh_ontology::Ontology::builtin_with_packs(&["research"]).unwrap());
    let dynamics = Arc::new(DynamicsStore::open(&dir.path().join("dyn.db"), None).unwrap());
    let store = Arc::new(
        StatementStore::open(
            &dir.path().join("lance"),
            DIM,
            ontology,
            dynamics,
            Arc::new(FixedEmbedder(Arc::new(HashEmbedder))),
            TestClock::at(t0()),
        )
        .await
        .unwrap(),
    );
    let db = Arc::new(ResearchDb::open(Path::new(&db_path), None).unwrap());
    let results = ResultService::new(store.clone(), db.clone(), "measure");
    let service = CitationService::new(store, db.clone(), GraphSlot::default());
    let resolver = if std::env::var("SHODH_LIVE_OPENALEX").as_deref() == Ok("1") {
        Resolver::online(Arc::new(SafeClient::system()), db.clone())
            .with_limits(1_500, super::resolve::MIN_INTERVAL)
    } else {
        Resolver::cache_only(db.clone())
    };
    let mut files = Vec::new();
    pdfs_under(Path::new(&corpus), &mut files);
    let files: Vec<String> = files.iter().map(|p| p.display().to_string()).collect();
    let report = service
        .build(&files, &results, &resolver, &|_| {})
        .await
        .unwrap();
    println!("{}", serde_json::to_string_pretty(&report).unwrap());
    let graph = service.graph(&results).await.unwrap();
    for paper in graph.papers().iter().filter(|p| p.in_library) {
        println!(
            "library: {} | arXiv {:?} | OpenAlex {:?} | cites {} | cited by {} in library",
            paper.label(),
            paper.arxiv_id,
            paper.openalex_id,
            graph.cited(&paper.id).len(),
            graph.citers(&paper.id).len()
        );
    }
    for hit in graph.most_cited(10, 2) {
        println!(
            "most cited: {} ({} library papers)",
            hit.paper.label(),
            hit.count
        );
    }
}

//! What one library PDF contributes to the graph, read from its parsed layout: its
//! identity, its references, and the headings and captions the deterministic method and
//! dataset rules read. A scan is stored in `shodh.db` per file fingerprint (size and
//! modification time), so a rebuild parses only files that changed.

use serde::{Deserialize, Serialize};

use super::identity::{identify, LocalIdentity, PdfInfo};
use super::reference::{parse_reference, ParsedReference};
use super::segment::{segment, BibBlock, EntryRegion, RejectReason};
use super::text::clean_block_text;
use crate::processing::document_model::{BlockKind, StructuredDocument};

/// Version of the scan rules; a stored scan of another version is redone.
pub const SCAN_VERSION: &str = "citation-scan/1";
/// Most references kept per paper (a survey's bibliography beyond this is cut).
pub const MAX_REFERENCES: usize = 400;
/// Most headings and captions kept per paper.
const MAX_LABELS: usize = 200;

/// One reference of a library paper.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ScannedReference {
    /// Position in the bibliography (0-based).
    pub index: usize,
    pub page: Option<u32>,
    #[serde(default)]
    pub regions: Vec<EntryRegion>,
    pub parsed: ParsedReference,
}

/// The scan of one PDF.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PaperScan {
    pub version: String,
    /// The file as spelled on disk.
    pub file_path: String,
    pub identity: LocalIdentity,
    pub references: Vec<ScannedReference>,
    /// Bibliography blocks or texts not used, per reason.
    pub rejected: Vec<(RejectReason, usize)>,
    /// References dropped beyond [`MAX_REFERENCES`].
    #[serde(default)]
    pub truncated: usize,
    /// Section headings, in order.
    pub headings: Vec<String>,
    /// Figure and table captions, in order.
    pub captions: Vec<String>,
    /// Pages in the document.
    pub pages: usize,
}

impl PaperScan {
    /// References that identify a work (see [`ParsedReference::is_identifiable`]).
    pub fn identifiable(&self) -> impl Iterator<Item = &ScannedReference> {
        self.references
            .iter()
            .filter(|r| r.parsed.is_identifiable())
    }
}

/// Scans a parsed PDF. `file_path` is the file as spelled on disk; `info` its Info
/// dictionary.
pub fn scan_document(doc: &StructuredDocument, info: &PdfInfo, file_path: &str) -> PaperScan {
    let file_name = crate::research::file_name(file_path);
    let identity = identify(doc, info, &file_name);
    let blocks: Vec<BibBlock> = doc
        .blocks
        .iter()
        .filter(|b| matches!(b.kind, BlockKind::ReferenceEntry))
        .map(|b| BibBlock {
            text: b.text.clone(),
            page: b.page,
            bbox: b.bbox,
            section_path: b.section_path.clone(),
        })
        .collect();
    let segmentation = segment(&blocks);
    let mut rejected: std::collections::BTreeMap<RejectReason, usize> = Default::default();
    for (reason, _) in &segmentation.rejected {
        *rejected.entry(*reason).or_insert(0) += 1;
    }
    let total = segmentation.entries.len();
    let references: Vec<ScannedReference> = segmentation
        .entries
        .into_iter()
        .take(MAX_REFERENCES)
        .enumerate()
        .map(|(index, entry)| ScannedReference {
            index,
            page: entry.page,
            regions: entry.regions,
            parsed: parse_reference(&entry.text),
        })
        .collect();
    let mut headings = Vec::new();
    let mut captions = Vec::new();
    for block in &doc.blocks {
        match &block.kind {
            BlockKind::Heading { .. } if headings.len() < MAX_LABELS => {
                headings.push(clean_block_text(&block.text));
            }
            BlockKind::Figure { caption } if captions.len() < MAX_LABELS => {
                captions.push(clean_block_text(caption));
            }
            BlockKind::Table {
                caption: Some(caption),
                ..
            } if captions.len() < MAX_LABELS => {
                captions.push(clean_block_text(caption));
            }
            _ => {}
        }
    }
    PaperScan {
        version: SCAN_VERSION.to_string(),
        file_path: file_path.to_string(),
        identity,
        truncated: total.saturating_sub(references.len()),
        references,
        rejected: rejected.into_iter().collect(),
        headings,
        captions,
        pages: doc.pages.len(),
    }
}

//! What the paper page, the method and dataset pages, the graph view and the agent tools
//! read from the graph, as serialisable values. Results and snippets of a paper are added
//! by the app (they live in the statement store under the paper's file).

use serde::Serialize;

use super::graph::{
    author_surname, CitationEvidence, ConceptNode, PaperFilter, PaperGraph, PaperHit, PaperNode,
    PathStep,
};

/// Most works listed per section of a paper page.
pub const MAX_LISTED: usize = 500;
/// Most related papers on a paper page.
pub const MAX_RELATED: usize = 12;
/// Most nodes sent to the graph view (it clusters what it does not draw).
pub const MAX_VIEW_NODES: usize = 3_000;

/// A cited or citing work with where the citation is printed.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LinkedPaper {
    pub paper: PaperNode,
    /// The reference entry in the citing library paper, when known.
    pub evidence: Option<CitationEvidence>,
    /// The library file that prints the reference.
    pub citing_file: Option<String>,
}

/// An author of a paper.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AuthorRef {
    pub id: String,
    pub name: String,
}

/// Links to a paper elsewhere.
#[derive(Debug, Clone, PartialEq, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PaperLinks {
    pub doi: Option<String>,
    pub arxiv: Option<String>,
    pub openalex: Option<String>,
}

/// Everything the graph says about one paper.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PaperView {
    pub paper: PaperNode,
    pub authors: Vec<AuthorRef>,
    pub links: PaperLinks,
    pub cites_in_library: Vec<LinkedPaper>,
    pub cites_elsewhere: Vec<LinkedPaper>,
    pub cited_by_in_library: Vec<LinkedPaper>,
    pub related: Vec<PaperHit>,
    pub methods: Vec<ConceptNode>,
    pub datasets: Vec<ConceptNode>,
    /// Methods this paper proposed (deterministic title/abstract rule).
    pub proposes: Vec<ConceptNode>,
}

/// Links of a paper.
pub fn links_of(paper: &PaperNode) -> PaperLinks {
    PaperLinks {
        doi: paper.doi.as_ref().map(|d| format!("https://doi.org/{d}")),
        arxiv: paper
            .arxiv_id
            .as_ref()
            .map(|a| format!("https://arxiv.org/abs/{a}")),
        openalex: paper
            .openalex_id
            .as_ref()
            .map(|o| format!("https://openalex.org/{o}")),
    }
}

fn authors_of(graph: &PaperGraph, paper: &PaperNode) -> Vec<AuthorRef> {
    let printed: Vec<String> = paper
        .authors
        .as_deref()
        .map(|a| {
            a.trim_end_matches(" et al.")
                .split(", ")
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default();
    paper
        .author_ids
        .iter()
        .enumerate()
        .map(|(i, id)| AuthorRef {
            id: id.clone(),
            name: graph
                .author_name(id)
                .map(str::to_string)
                .or_else(|| printed.get(i).cloned())
                .unwrap_or_else(|| author_surname(id)),
        })
        .collect()
}

/// The paper page of `id`.
pub fn paper_view(graph: &PaperGraph, id: &str) -> Option<PaperView> {
    let paper = graph.paper(id)?.clone();
    let mut cites_in_library = Vec::new();
    let mut cites_elsewhere = Vec::new();
    for cited in graph.cited(id).into_iter().take(MAX_LISTED) {
        let linked = LinkedPaper {
            evidence: graph.evidence(id, &cited.id).cloned(),
            citing_file: paper.file_path.clone(),
            paper: cited.clone(),
        };
        if cited.in_library {
            cites_in_library.push(linked);
        } else {
            cites_elsewhere.push(linked);
        }
    }
    cites_elsewhere.sort_by(|a, b| {
        b.paper
            .cited_by_count
            .cmp(&a.paper.cited_by_count)
            .then(a.paper.label().cmp(&b.paper.label()))
    });
    let cited_by_in_library = graph
        .citers(id)
        .into_iter()
        .filter(|p| p.in_library)
        .take(MAX_LISTED)
        .map(|citer| LinkedPaper {
            evidence: graph.evidence(&citer.id, id).cloned(),
            citing_file: citer.file_path.clone(),
            paper: citer.clone(),
        })
        .collect();
    let proposes = graph
        .methods()
        .filter(|m| graph.proposed_in(&m.id).is_some_and(|p| p.id == id))
        .cloned()
        .collect();
    Some(PaperView {
        authors: authors_of(graph, &paper),
        links: links_of(&paper),
        cites_in_library,
        cites_elsewhere,
        cited_by_in_library,
        related: graph.related(id, MAX_RELATED),
        methods: graph.methods_of(id).into_iter().cloned().collect(),
        datasets: graph.datasets_of(id).into_iter().cloned().collect(),
        proposes,
        paper,
    })
}

/// A method or dataset page.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ConceptView {
    pub concept: ConceptNode,
    /// `method` or `dataset`.
    pub kind: &'static str,
    pub papers: Vec<PaperNode>,
    /// The library paper that proposed the method, when the rule found one.
    pub proposed_in: Option<PaperNode>,
}

/// The page of a method (`kind` = `method`) or dataset, by id or label.
pub fn concept_view(graph: &PaperGraph, kind: &str, id_or_label: &str) -> Option<ConceptView> {
    let (kind, id) = match kind {
        "method" => (
            "method",
            if id_or_label.starts_with("method:") {
                id_or_label.to_string()
            } else {
                crate::research::results::canonical_id("method", id_or_label)
            },
        ),
        "dataset" => (
            "dataset",
            if id_or_label.starts_with("dataset:") {
                id_or_label.to_string()
            } else {
                crate::research::results::canonical_id("dataset", id_or_label)
            },
        ),
        _ => return None,
    };
    let concept = match kind {
        "method" => graph.method(&id)?.clone(),
        _ => graph.dataset(&id)?.clone(),
    };
    let papers = match kind {
        "method" => graph.papers_using(&id),
        _ => graph.papers_on(&id),
    }
    .into_iter()
    .cloned()
    .collect();
    Some(ConceptView {
        proposed_in: (kind == "method")
            .then(|| graph.proposed_in(&id).cloned())
            .flatten(),
        concept,
        kind,
        papers,
    })
}

/// One node of the graph view.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ViewNode {
    pub id: String,
    pub label: String,
    pub year: Option<i32>,
    pub in_library: bool,
    pub file_path: Option<String>,
    /// Library papers citing it.
    pub library_citers: usize,
    pub cited_by_count: Option<i64>,
    pub methods: Vec<String>,
}

/// The graph view's data: nodes (library papers first, then the most cited), edges among
/// them, and the methods for the filter.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GraphView {
    pub nodes: Vec<ViewNode>,
    /// `(citing, cited)` node ids.
    pub edges: Vec<(String, String)>,
    pub methods: Vec<ConceptNode>,
    /// Nodes left out beyond [`MAX_VIEW_NODES`].
    pub omitted: usize,
}

/// The graph view's data.
pub fn graph_view(graph: &PaperGraph) -> GraphView {
    let mut nodes: Vec<ViewNode> = graph
        .papers()
        .iter()
        .map(|p| ViewNode {
            id: p.id.clone(),
            label: p.label(),
            year: p.year,
            in_library: p.in_library,
            file_path: p.file_path.clone(),
            library_citers: graph.citers(&p.id).iter().filter(|c| c.in_library).count(),
            cited_by_count: p.cited_by_count,
            methods: graph
                .methods_of(&p.id)
                .iter()
                .map(|m| m.id.clone())
                .collect(),
        })
        .collect();
    nodes.sort_by(|a, b| {
        b.in_library
            .cmp(&a.in_library)
            .then(b.library_citers.cmp(&a.library_citers))
            .then(a.id.cmp(&b.id))
    });
    let omitted = nodes.len().saturating_sub(MAX_VIEW_NODES);
    nodes.truncate(MAX_VIEW_NODES);
    let kept: std::collections::HashSet<&str> = nodes.iter().map(|n| n.id.as_str()).collect();
    let edges = graph
        .edges()
        .into_iter()
        .filter(|(a, b)| kept.contains(a) && kept.contains(b))
        .map(|(a, b)| (a.to_string(), b.to_string()))
        .collect();
    GraphView {
        nodes,
        edges,
        methods: graph.methods().cloned().collect(),
        omitted,
    }
}

/// `find_papers` over the graph.
pub fn find(graph: &PaperGraph, filter: &PaperFilter, limit: usize) -> Vec<PaperNode> {
    graph
        .find_papers(filter)
        .into_iter()
        .take(limit)
        .cloned()
        .collect()
}

/// A lineage path, for the tool.
pub fn lineage(graph: &PaperGraph, from: &str, to: &str) -> Option<Vec<PathStep>> {
    graph.lineage(from, to, 6)
}

