        assert_eq!(id.identifier_source, Some(IdentifierSource::PdfInfo));
        assert_eq!(id.filename_arxiv_id, None);
        let info = PdfInfo {
            title: Some("Long Short-Term Memory".into()),
            ..PdfInfo::default()
        };
        assert_eq!(
            identify(&d, &info, "x.pdf").title_source,
            Some(TitleSource::PdfInfo)
        );
    }

    #[test]
    fn a_heading_taken_for_the_title_falls_back_to_the_first_page_lines() {
        let d = doc(vec![
            Block::new(
                BlockKind::Paragraph,
                "It’s All Connected: A Journey Through Test-Time Memorization,",
            )
            .on_page(1, None),
            Block::new(
                BlockKind::Paragraph,
                "Attentional Bias, Retention, and Online Optimization",
            )
            .on_page(1, None),
            Block::new(BlockKind::Title, "1 Introduction").on_page(1, None),
        ]);
        let id = identify(&d, &PdfInfo::default(), "paper.pdf");
        assert_eq!(
            id.title.as_deref(),
            Some("It’s All Connected: A Journey Through Test-Time Memorization, Attentional Bias, Retention, and Online Optimization")
        );
        let d = doc(vec![
            Block::new(BlockKind::Title, "A Title").on_page(1, None),
            Block::new(
                BlockKind::Paragraph,
                "Songlin Yang⋄ Yoon Kim⋄ ⋄Massachusetts Institute of Technology",
            )
            .on_page(1, None),
        ]);
        let surnames: Vec<String> = identify(&d, &PdfInfo::default(), "x.pdf")
            .authors
            .iter()
            .map(|a| a.family.clone())
            .collect();
        assert_eq!(surnames, ["Yang", "Kim"]);
    }

    #[test]
    fn arxiv_years_and_file_name_hints() {
        assert_eq!(arxiv_year("2102.11174"), Some(2021));
        assert_eq!(arxiv_year("2113.11174"), None);
        assert_eq!(
            filename_arxiv_id("2411.12537 - Unlocking State-Tracking.pdf").as_deref(),
            Some("2411.12537")
        );
        assert_eq!(
            filename_arxiv_id("KAN - Kolmogorov-Arnold Networks.pdf"),
            None
        );
    }
}

//! Turning the bibliography blocks of a parsed paper into one text per reference.
//!
//! The layout parser marks every paragraph after a "References" heading as a bibliography
//! entry until the next top-level heading, so its blocks are not yet one reference each:
//! - an entry split across columns or pages arrives as two blocks;
//! - two short entries can arrive as one block;
//! - appendix paragraphs under a lower-level heading after the bibliography arrive as
//!   entries too.
//!
//! [`segment`] re-splits blocks on numbered markers (`[12]`, `12.`), merges continuation
//! fragments into the entry before them and rejects what is not shaped like a reference,
//! counting each rejection with its reason rather than guessing.

use std::sync::LazyLock;

use regex::Regex;
use serde::{Deserialize, Serialize};

use super::reference::take_authors;
use super::text::clean_block_text;
use crate::processing::document_model::{is_references_heading, BBox};

/// Longest text accepted as one reference, in characters.
pub const MAX_ENTRY_CHARS: usize = 1_200;
/// Shortest text accepted as one reference, in words.
pub const MIN_ENTRY_WORDS: usize = 4;

/// One bibliography block of the parsed document.
#[derive(Debug, Clone, PartialEq)]
pub struct BibBlock {
    pub text: String,
    pub page: Option<u32>,
    pub bbox: Option<BBox>,
    pub section_path: Vec<String>,
}

/// A box of an entry on a page (bottom-left origin, PDF points).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct EntryRegion {
    pub page: u32,
    pub x0: f32,
    pub y0: f32,
    pub x1: f32,
    pub y1: f32,
}

/// The text of one reference and where it is printed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RawEntry {
    pub text: String,
    pub page: Option<u32>,
    /// Boxes of the blocks the entry was assembled from. A block that held several
    /// entries gives its box to each of them.
    pub regions: Vec<EntryRegion>,
}

/// Why a block was not used as a reference.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RejectReason {
    /// Under a heading other than the bibliography's (an appendix after it).
    OutsideBibliography,
    /// Longer than any reference ([`MAX_ENTRY_CHARS`]).
    TooLong,
    /// Fewer than [`MIN_ENTRY_WORDS`] words.
    TooShort,
    /// No year, identifier or author list.
    NotAReference,
    /// A continuation fragment with no entry before it.
    Orphan,
}

/// The segmentation of one paper's bibliography.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Segmentation {
    pub entries: Vec<RawEntry>,
    /// Rejected blocks or assembled texts, with the reason.
    pub rejected: Vec<(RejectReason, String)>,
    /// The bibliography is numbered (`[n]` or `n.`).
    pub numbered: bool,
}

static NUMBER_MARKER: LazyLock<Option<Regex>> =
    LazyLock::new(|| Regex::new(r"^\s*(?:\[(\d{1,3})\]|(\d{1,3})\.\s)").ok());
static INNER_MARKER: LazyLock<Option<Regex>> =
    LazyLock::new(|| Regex::new(r"\s\[(\d{1,3})\]\s").ok());
static HAS_YEAR: LazyLock<Option<Regex>> =
    LazyLock::new(|| Regex::new(r"(?:^|[^0-9])(?:19[5-9]\d|20[0-4]\d)[a-z]?(?:[^0-9]|$)").ok());
static HAS_IDENTIFIER: LazyLock<Option<Regex>> =
    LazyLock::new(|| Regex::new(r"(?i)10\.\d{4,9}/|arxiv|abs/\d{4}\.\d{4,5}|https?://").ok());

fn marker_number(text: &str) -> Option<u32> {
    let c = NUMBER_MARKER.as_ref()?.captures(text)?;
    c.get(1).or_else(|| c.get(2))?.as_str().parse().ok()
}

fn matches(re: &LazyLock<Option<Regex>>, text: &str) -> bool {
    re.as_ref().is_some_and(|r| r.is_match(text))
}

fn region_of(block: &BibBlock) -> Option<EntryRegion> {
    match (block.page, block.bbox) {
        (Some(page), Some(b)) => Some(EntryRegion {
            page,
            x0: b.x0,
            y0: b.y0,
            x1: b.x1,
            y1: b.y1,
        }),
        _ => None,
    }
}

/// Whether the block sits directly under the bibliography heading.
fn in_bibliography(block: &BibBlock) -> bool {
    match block.section_path.last() {
        Some(heading) => is_references_heading(heading),
        // No heading chain (unpaged sources): trust the parser.
        None => true,
    }
}

/// Whether text reads as the start of an author–year entry: an author list at its start.
fn starts_like_entry(text: &str) -> bool {
    let first = text.chars().next();
    if !first.is_some_and(char::is_uppercase) {
        return false;
    }
    let (authors, _, _) = take_authors(text);
    !authors.is_empty()
}

/// Whether text continues the entry before it (it cannot start one).
fn continues_entry(text: &str) -> bool {
    let Some(first) = text.chars().next() else {
        return false;
    };
    if first.is_lowercase() || first.is_ascii_digit() || matches!(first, '(' | ',' | ';' | ':') {
        return true;
    }
    let lower = text.to_lowercase();
    [
        "in ",
        "pp.",
        "pages ",
        "proceedings",
        "arxiv",
        "url ",
        "doi",
        "advances in",
        "journal ",
        "transactions",
        "springer",
        "ieee",
        "acm ",
        "pmlr",
        "openreview",
    ]
    .iter()
    .any(|p| lower.starts_with(p))
}

/// Splits a block of a numbered bibliography at inner markers that continue the numbering
/// (`… 2021. [13] K. Irie …` after entry 12).
fn split_numbered(text: &str, expected_next: Option<u32>) -> Vec<String> {
    let Some(re) = INNER_MARKER.as_ref() else {
        return vec![text.to_string()];
    };
    let mut out = Vec::new();
    let mut start = 0;
    let mut next = marker_number(text).map(|n| n + 1).or(expected_next);
    for c in re.captures_iter(text) {
        let (Some(whole), Some(number)) = (c.get(0), c.get(1)) else {
            continue;
        };
        let n: Option<u32> = number.as_str().parse().ok();
        if n.is_some() && n == next {
            let piece = text[start..whole.start()].trim();
            if !piece.is_empty() {
                out.push(piece.to_string());
            }
            start = whole.start() + 1;
            next = n.map(|v| v + 1);
        }
    }
    let tail = text[start..].trim();
    if !tail.is_empty() {
        out.push(tail.to_string());
    }
    out
}

fn reject_shape(text: &str) -> Option<RejectReason> {
    if text.chars().count() > MAX_ENTRY_CHARS {
        return Some(RejectReason::TooLong);
    }
    if text.split_whitespace().count() < MIN_ENTRY_WORDS {
        return Some(RejectReason::TooShort);
    }
    let body = match NUMBER_MARKER.as_ref().and_then(|r| r.find(text)) {
        Some(m) => &text[m.end()..],
        None => text,
    };
    let has_authors = !take_authors(body.trim_start()).0.is_empty();
    if !matches(&HAS_YEAR, text) && !matches(&HAS_IDENTIFIER, text) && !has_authors {
        return Some(RejectReason::NotAReference);
    }
    None
}

fn preview(text: &str) -> String {
    let mut p: String = text.chars().take(120).collect();
    if text.chars().count() > 120 {
        p.push('…');
    }
    p
}

/// Segments the bibliography blocks of one paper, in reading order.
pub fn segment(blocks: &[BibBlock]) -> Segmentation {
    let mut out = Segmentation::default();
    let mut kept: Vec<(String, &BibBlock)> = Vec::new();
    for block in blocks {
        let text = clean_block_text(&block.text);
        if text.is_empty() {
            continue;
        }
        if !in_bibliography(block) {
            out.rejected
                .push((RejectReason::OutsideBibliography, preview(&text)));
            continue;
        }
        kept.push((text, block));
    }
    let numbered_blocks = kept
        .iter()
        .filter(|(t, _)| marker_number(t).is_some())
        .count();
    // Line-split bibliographies have many continuation blocks per numbered entry, so a
    // quarter of blocks starting with `[n]` already marks the style.
    out.numbered = !kept.is_empty() && numbered_blocks * 4 >= kept.len();

    let mut assembled: Vec<RawEntry> = Vec::new();
    let mut last_number: Option<u32> = None;
    for (text, block) in kept {
        let region = region_of(block);
        let pieces = if out.numbered {
            split_numbered(&text, last_number.map(|n| n + 1))
        } else {
            vec![text]
        };
        for piece in pieces {
            let starts = if out.numbered {
                marker_number(&piece).is_some()
            } else {
                match assembled.last() {
                    None => true,
                    // A line-split entry: the previous text stops mid-sentence.
                    Some(prev) if !ends_sentence(&prev.text) => false,
                    Some(prev) => {
                        !continues_entry(&piece)
                            && (starts_like_entry(&piece) || entry_complete(&prev.text))
                    }
                }
            };
            if starts {
                if let Some(n) = marker_number(&piece) {
                    last_number = Some(n);
                }
                assembled.push(RawEntry {
                    text: piece,
                    page: block.page,
                    regions: region.into_iter().collect(),
                });
            } else if let Some(prev) = assembled.last_mut() {
                // A line break, so the parser joins a word hyphenated across it.
                prev.text.push('\n');
                prev.text.push_str(&piece);
                if let Some(r) = region {
                    if !prev.regions.contains(&r) {
                        prev.regions.push(r);
                    }
                }
            } else {
                out.rejected.push((RejectReason::Orphan, preview(&piece)));
            }
        }
    }
    for entry in assembled {
        match reject_shape(&entry.text) {
            Some(reason) => out.rejected.push((reason, preview(&entry.text))),
            None => out.entries.push(entry),
        }
    }
    out
}

/// Whether text ends a sentence (a period, possibly before a closing bracket or quote).
fn ends_sentence(text: &str) -> bool {
    text.trim_end()
        .trim_end_matches([')', ']', '"', '\u{201d}', '\''])
        .ends_with('.')
}

/// Whether an author–year entry already looks complete: it has a year and ends with a
/// period (a fragment after it starts a new entry).
fn entry_complete(text: &str) -> bool {
    matches(&HAS_YEAR, text) && ends_sentence(text)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn block(text: &str, page: u32) -> BibBlock {
        BibBlock {
            text: text.to_string(),
            page: Some(page),
            bbox: Some(BBox::new(72.0, 100.0, 300.0, 120.0)),
            section_path: vec!["References".to_string()],
        }
    }

    #[test]
    fn numbered_blocks_split_at_markers_and_merge_continuations() {
        let blocks = vec![
            block("[1] S. Hochreiter and J. Schmidhuber. Long short-term memory. Neural Computation, 1997. [2] A. Vaswani, N. Shazeer, and N. Parmar. Attention is all you need.", 9),
            block("In NeurIPS, 2017.", 9),
            block("[3] I. Schlag, K. Irie, and J. Schmidhuber. Linear transformers are secretly fast weight programmers. In ICML, 2021.", 10),
        ];
        let s = segment(&blocks);
        assert!(s.numbered);
        assert_eq!(s.entries.len(), 3, "{:?}", s.entries);
        assert!(s.entries[1]
            .text
            .ends_with("Attention is all you need.\nIn NeurIPS, 2017."));
        assert!(s.entries[2].text.starts_with("[3] I. Schlag"));
        assert_eq!(s.entries[2].page, Some(10));
        assert!(s.rejected.is_empty());
    }

    #[test]
    fn author_year_fragments_join_the_entry_before_them() {
        let blocks = vec![
            block("Imanol Schlag, Kazuki Irie, and Jürgen Schmidhuber. 2021. Linear transformers are secretly fast weight programmers. In International Conference on Machine", 11),
            block("Learning, pages 9355–9366. PMLR.", 12),
            block("Songlin Yang, Bailin Wang, Yu Zhang, Yikang Shen, and Yoon Kim. 2024. Parallelizing linear transformers with the delta rule over sequence length. In NeurIPS.", 12),
        ];
        let s = segment(&blocks);
        assert!(!s.numbered);
        assert_eq!(s.entries.len(), 2, "{:?}", s.entries);
        assert!(s.entries[0]
            .text
            .ends_with("Machine\nLearning, pages 9355–9366. PMLR."));
        assert_eq!(s.entries[0].regions.len(), 2);
    }

    #[test]
    fn line_split_author_lists_join_until_the_entry_ends() {
        let blocks = vec![
            block("Achiam, J., Adler, S., Agarwal, S., Ahmad, L., Akkaya, I., Aleman, F. L., Almeida, D., Altenschmidt,", 14),
            block("J., Altman, S., Anadkat, S., et al. Gpt-4 technical report. arXiv preprint arXiv:2303.08774, 2023.", 14),
            block("Artetxe, M., Ruder, S., and Yogatama, D. On the cross-lingual transferability of monolingual represen-", 14),
            block("tations. In ACL, 2020.", 14),
        ];
        let s = segment(&blocks);
        assert_eq!(s.entries.len(), 2, "{:?}", s.entries);
        assert!(clean_block_text(&s.entries[0].text).contains("Altenschmidt, J., Altman"));
        assert!(s.entries[1].text.contains("represen-\ntations"));
        assert!(clean_block_text(&s.entries[1].text).contains("monolingual representations"));
    }

    #[test]
    fn appendix_paragraphs_and_non_references_are_rejected_with_reasons() {
        let mut appendix = block(
            "We additionally conduct experiments on RegBench, a synthetic data set designed to assess in-context learning.",
            14,
        );
        appendix.section_path = vec!["References".into(), "A.2 Synthetic tasks".into()];
        let blocks = vec![
            block("Hochreiter, S., & Schmidhuber, J. (1997). Long short-term memory. Neural Computation, 9(8), 1735–1780.", 9),
            appendix,
            block(&"Word ".repeat(400), 9),
        ];
        let s = segment(&blocks);
        assert_eq!(s.entries.len(), 1);
        let reasons: Vec<RejectReason> = s.rejected.iter().map(|(r, _)| *r).collect();
        assert!(reasons.contains(&RejectReason::OutsideBibliography));
        assert!(reasons.contains(&RejectReason::TooLong));
    }
}

//! Resolving papers to OpenAlex works: identifier lookups, a strict title match, a cache in
//! `shodh.db` and a polite request pace.
//!
//! What is sent: only bibliographic identifiers (a DOI, or an arXiv id as its arXiv DOI)
//! and, for references without one, the reference's title with its year range. Document
//! text is never sent, and neither is a library paper's own title (a paper of the user's
//! may be unpublished): a library paper is looked up by its DOI or arXiv id only.
//!
//! Matching ([`strict_match`]): a title search result is accepted only when its title is at
//! least [`TITLE_THRESHOLD`] similar to the reference's, its year is within one of the
//! reference's and its first author has the reference's first-author surname. An
//! identifier lookup is accepted unless both titles are known and plainly disagree (a
//! mistyped DOI).
//!
//! Requests go through [`SafeClient`] (SSRF checks, the app's generic User-Agent, no
//! e-mail or other identifying header), at most one every [`MIN_INTERVAL`], at most
//! [`DEFAULT_BUDGET`] per build, and stop for the build when the API answers 429. Every
//! answer, including "not found", is cached in `scholarly_cache` ([`POSITIVE_TTL_DAYS`],
//! [`NEGATIVE_TTL_DAYS`]), so a rebuild sends nothing for what it already asked.

use std::sync::Arc;
use std::time::Duration;

use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::sync::Mutex;
use url::Url;

use super::text::{normalize_surname, title_similarity};
use crate::harness::web::papers::{normalize_arxiv_id, normalize_doi, OPENALEX_API};
use crate::harness::web::{SafeClient, WebError};
use crate::research::db::ResearchDb;
use crate::research::{blocking, ResearchError, ResearchResult};

/// Lowest title similarity a title search result needs.
pub const TITLE_THRESHOLD: f64 = 0.9;
/// Below this similarity an identifier lookup's title disagrees with the reference.
pub const IDENTIFIER_TITLE_FLOOR: f64 = 0.5;
/// Pause between two requests.
pub const MIN_INTERVAL: Duration = Duration::from_millis(250);
/// Pause before the one retry after a 429 (too many requests).
pub const RATE_LIMIT_BACKOFF: Duration = Duration::from_secs(20);
/// Most requests one build sends.
pub const DEFAULT_BUDGET: usize = 400;
/// How long a found work is reused before it is asked again.
pub const POSITIVE_TTL_DAYS: i64 = 30;
/// How long "not found" is remembered.
pub const NEGATIVE_TTL_DAYS: i64 = 7;
/// Largest answer read.
const MAX_ANSWER_BYTES: u64 = 2 * 1024 * 1024;
/// Results asked of a title search.
const SEARCH_RESULTS: usize = 5;
/// Fields asked of OpenAlex (keeps answers small).
const SELECT: &str =
    "id,doi,display_name,publication_year,authorships,primary_location,cited_by_count,ids,type";
/// arXiv's DOI prefix.
const ARXIV_DOI_PREFIX: &str = "10.48550/arxiv.";

/// One OpenAlex work, reduced to what the graph uses.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OpenAlexWork {
    /// `W…` id.
    pub id: String,
    pub doi: Option<String>,
    pub arxiv_id: Option<String>,
    pub title: String,
    pub year: Option<i32>,
    /// Display names, in author order.
    pub authors: Vec<String>,
    pub venue: Option<String>,
    pub cited_by_count: Option<i64>,
}

impl OpenAlexWork {
    /// Comparable surnames of the first author's name (every word of it, so `Yang
    /// Songlin` and `Songlin Yang` both match `yang`).
    fn first_author_words(&self) -> Vec<String> {
        self.authors
            .first()
            .map(|name| {
                name.split([' ', '-'])
                    .map(normalize_surname)
                    .filter(|w| w.len() > 1)
                    .collect()
            })
            .unwrap_or_default()
    }
}

/// `W123` from `https://openalex.org/W123` or `W123`.
pub fn openalex_id(raw: &str) -> Option<String> {
    let id = raw.trim().rsplit('/').next()?.to_string();
    let digits = id.strip_prefix('W')?;
    (!digits.is_empty() && digits.len() <= 12 && digits.chars().all(|c| c.is_ascii_digit()))
        .then_some(id)
}

/// Reads one work object.
pub fn parse_work(work: &Value) -> Option<OpenAlexWork> {
    let text = |ptr: &str| {
        work.pointer(ptr)
            .and_then(Value::as_str)
            .map(|s| s.split_whitespace().collect::<Vec<_>>().join(" "))
            .filter(|s| !s.is_empty())
    };
    let id = text("/id").and_then(|i| openalex_id(&i))?;
    let title = text("/display_name").or_else(|| text("/title"))?;
    let doi = text("/doi").and_then(|d| normalize_doi(&d));
    let arxiv_id = doi
        .as_deref()
        .and_then(normalize_arxiv_id)
        .or_else(|| text("/ids/arxiv").and_then(|a| normalize_arxiv_id(&a)))
        .or_else(|| {
            text("/primary_location/landing_page_url").and_then(|u| normalize_arxiv_id(&u))
        });
    let authors = work
        .get("authorships")
        .and_then(Value::as_array)
        .map(|list| {
            list.iter()
                .filter_map(|a| {
                    a.pointer("/author/display_name")
                        .and_then(Value::as_str)
                        .or_else(|| a.get("raw_author_name").and_then(Value::as_str))
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                })
                .collect()
        })
        .unwrap_or_default();
    Some(OpenAlexWork {
        id,
        doi,
        arxiv_id,
        title,
        year: work
            .get("publication_year")
            .and_then(Value::as_i64)
            .and_then(|y| i32::try_from(y).ok()),
        authors,
        venue: text("/primary_location/source/display_name"),
        cited_by_count: work.get("cited_by_count").and_then(Value::as_i64),
    })
}

/// Reads the `results` of a `/works` list answer.
pub fn parse_work_list(answer: &Value) -> Vec<OpenAlexWork> {
    answer
        .get("results")
        .and_then(Value::as_array)
        .map(|list| list.iter().filter_map(parse_work).collect())
        .unwrap_or_default()
}

/// What is looked up.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum WorkRequest {
    /// A DOI (an arXiv id is looked up as its arXiv DOI).
    Doi(String),
    /// A reference's title within a year range.
    Title { title: String, year: Option<i32> },
}

impl WorkRequest {
    /// The lookup of an arXiv id.
    pub fn arxiv(id: &str) -> Self {
        WorkRequest::Doi(format!("{ARXIV_DOI_PREFIX}{}", id.to_ascii_lowercase()))
    }

    /// The cache key: the request in a canonical spelling.
    pub fn cache_key(&self) -> String {
        match self {
            WorkRequest::Doi(doi) => format!("openalex:doi:{}", doi.to_ascii_lowercase()),
            WorkRequest::Title { title, year } => format!(
                "openalex:title:{}:{}",
                title_filter_text(title),
                year.map(|y| y.to_string()).unwrap_or_default()
            ),
        }
    }

    /// The OpenAlex URL of the request.
    pub fn url(&self) -> Result<Url, WebError> {
        let parse = |s: &str| Url::parse(s).map_err(|e| WebError::Http(e.to_string()));
        match self {
            WorkRequest::Doi(doi) => {
                let mut url = parse(&format!("{OPENALEX_API}/doi:{doi}"))?;
                url.query_pairs_mut().append_pair("select", SELECT);
                Ok(url)
            }
            WorkRequest::Title { title, year } => {
                let mut filter = format!("title.search:{}", title_filter_text(title));
                if let Some(y) = year {
                    filter.push_str(&format!(",publication_year:{}-{}", y - 1, y + 1));
                }
                let mut url = parse(OPENALEX_API)?;
                url.query_pairs_mut()
                    .append_pair("filter", &filter)
                    .append_pair("per-page", &SEARCH_RESULTS.to_string())
                    .append_pair("select", SELECT);
                Ok(url)
            }
        }
    }
}

/// A title as an OpenAlex filter value: filter values are split on `,` and `|` and `:`
/// separates a filter's name, so only letters, digits and spaces are kept.
fn title_filter_text(title: &str) -> String {
    title
        .chars()
        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

/// What a reference says about the work it cites, for matching.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct WorkQuery {
    pub title: Option<String>,
    pub year: Option<i32>,
    pub first_surname: Option<String>,
}

/// Whether a work matches.
#[derive(Debug, Clone, PartialEq)]
pub enum MatchVerdict {
    Accepted { similarity: f64 },
    Rejected { reason: String },
}

impl MatchVerdict {
    pub fn accepted(&self) -> bool {
        matches!(self, MatchVerdict::Accepted { .. })
    }
}

/// The strict title-search rule (see the module documentation). All three of title, year
/// and first-author surname must be known on the reference side.
pub fn strict_match(query: &WorkQuery, work: &OpenAlexWork) -> MatchVerdict {
    let reject = |reason: String| MatchVerdict::Rejected { reason };
    let (Some(title), Some(year), Some(surname)) =
        (&query.title, query.year, query.first_surname.as_deref())
    else {
        return reject("the reference lacks a title, year or first author".into());
    };
    let similarity = title_similarity(title, &work.title);
    if similarity < TITLE_THRESHOLD {
        return reject(format!(
            "title similarity {similarity:.2} < {TITLE_THRESHOLD}"
        ));
    }
    match work.year {
        Some(y) if (y - year).abs() <= 1 => {}
        Some(y) => return reject(format!("year {y} is not within one of {year}")),
        None => return reject("the work has no year".into()),
    }
    let surname = normalize_surname(surname);
    if !work.first_author_words().contains(&surname) {
        return reject(format!(
            "first author {} is not {surname}",
            work.authors.first().map(String::as_str).unwrap_or("(none)")
        ));
    }
    MatchVerdict::Accepted { similarity }
}

/// The rule for identifier lookups: accepted unless both titles are known and their
/// similarity is below [`IDENTIFIER_TITLE_FLOOR`].
pub fn identifier_match(title: Option<&str>, work: &OpenAlexWork) -> MatchVerdict {
    match title {
        Some(t) => {
            let similarity = title_similarity(t, &work.title);
            if similarity < IDENTIFIER_TITLE_FLOOR {
                MatchVerdict::Rejected {
                    reason: format!(
                        "the identifier names \"{}\", whose title disagrees ({similarity:.2})",
                        work.title
                    ),
                }
            } else {
                MatchVerdict::Accepted { similarity }
            }
        }
        None => MatchVerdict::Accepted { similarity: 1.0 },
    }
}

/// Why nothing more is looked up in this build.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case", tag = "kind", content = "detail")]
pub enum Halt {
    /// The resolver reads only cached answers (the web is not allowed): nothing is sent.
    Offline,
    /// The per-build request budget is spent.
    Budget,
    /// The API answered 429 (too many requests).
    RateLimited,
    /// The API could not be reached.
    Unreachable(String),
}

/// What one lookup gave.
#[derive(Debug, Clone, PartialEq)]
pub enum Lookup {
    /// Works the API returned (one for a DOI; up to five for a title).
    Works(Vec<OpenAlexWork>),
    /// The API knows no such work.
    NotFound,
    /// Not asked: the build halted.
    Halted(Halt),
}

/// Counters of one build's lookups.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LookupStats {
    pub requests: usize,
    pub cache_hits: usize,
    pub not_found: usize,
    pub errors: usize,
}

/// Fetches the JSON answer of a URL. Production uses [`SafeClient`]; tests record or
/// replay answers.
#[async_trait::async_trait]
pub trait ScholarlyTransport: Send + Sync {
    /// The status and body of a GET.
    async fn get(&self, url: &Url) -> Result<(u16, Vec<u8>), WebError>;
}

#[async_trait::async_trait]
impl ScholarlyTransport for SafeClient {
    async fn get(&self, url: &Url) -> Result<(u16, Vec<u8>), WebError> {
        let fetched = SafeClient::get(self, url.as_str(), Vec::new()).await?;
        let status = fetched.status;
        let body = fetched.read_capped(MAX_ANSWER_BYTES).await?;
        Ok((status, body))
    }
}

struct Pace {
    last: Option<tokio::time::Instant>,
    halted: Option<Halt>,
    stats: LookupStats,
}

/// Cached, paced OpenAlex lookups for one build. [`Resolver::online`] is created only when
/// the user's policy allows the web (see the app's graph command); otherwise
/// [`Resolver::cache_only`] reads answers already cached on this computer and sends
/// nothing.
pub struct Resolver {
    transport: Option<Arc<dyn ScholarlyTransport>>,
    db: Arc<ResearchDb>,
    budget: usize,
    interval: Duration,
    backoff: Duration,
    pace: Mutex<Pace>,
}

impl std::fmt::Debug for Resolver {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Resolver")
            .field("budget", &self.budget)
            .finish_non_exhaustive()
    }
}

impl Resolver {
    /// Lookups that may go to OpenAlex.
    pub fn online(transport: Arc<dyn ScholarlyTransport>, db: Arc<ResearchDb>) -> Self {
        Self::with_transport(Some(transport), db)
    }

    /// Lookups from the cache only: a miss is [`Halt::Offline`] and nothing is sent.
    pub fn cache_only(db: Arc<ResearchDb>) -> Self {
        Self::with_transport(None, db)
    }

    fn with_transport(transport: Option<Arc<dyn ScholarlyTransport>>, db: Arc<ResearchDb>) -> Self {
        Self {
            transport,
            db,
            budget: DEFAULT_BUDGET,
            interval: MIN_INTERVAL,
            backoff: RATE_LIMIT_BACKOFF,
            pace: Mutex::new(Pace {
                last: None,
                halted: None,
                stats: LookupStats::default(),
            }),
        }
    }

    /// Another request budget and pause (tests use a zero pause and back-off).
    pub fn with_limits(mut self, budget: usize, interval: Duration) -> Self {
        self.budget = budget;
        self.interval = interval;
        self.backoff = interval.min(self.backoff);
        self
    }

    /// Whether lookups may go to the network.
    pub fn is_online(&self) -> bool {
        self.transport.is_some()
    }

    /// Counters so far.
    pub async fn stats(&self) -> LookupStats {
        self.pace.lock().await.stats
    }

    /// Why lookups stopped, if they did.
    pub async fn halted(&self) -> Option<Halt> {
        self.pace.lock().await.halted.clone()
    }

    /// One lookup: from the cache when fresh, else from the API (paced, within budget).
    pub async fn lookup(&self, request: &WorkRequest) -> ResearchResult<Lookup> {
        let key = request.cache_key();
        let db = self.db.clone();
        let cache_key = key.clone();
        if let Some((status, body)) = blocking(move || db.cached_answer(&cache_key)).await? {
            self.pace.lock().await.stats.cache_hits += 1;
            return Ok(decode(request, status, &body));
        }
        let Some(transport) = self.transport.as_ref() else {
            return Ok(Lookup::Halted(Halt::Offline));
        };
        let mut pace = self.pace.lock().await;
        if let Some(halt) = &pace.halted {
            return Ok(Lookup::Halted(halt.clone()));
        }
        if pace.stats.requests >= self.budget {
            pace.halted = Some(Halt::Budget);
            return Ok(Lookup::Halted(Halt::Budget));
        }
        if let Some(last) = pace.last {
            let wait = self.interval.saturating_sub(last.elapsed());
            if !wait.is_zero() {
                tokio::time::sleep(wait).await;
            }
        }
        pace.last = Some(tokio::time::Instant::now());
        pace.stats.requests += 1;
        let url = request
            .url()
            .map_err(|e| ResearchError::Invalid(e.to_string()))?;
        let mut answer = transport.get(&url).await;
        // One 429 is answered by waiting and asking once more; a second halts the build.
        if matches!(answer, Ok((429, _))) && pace.stats.requests < self.budget {
            tokio::time::sleep(self.backoff).await;
            pace.last = Some(tokio::time::Instant::now());
            pace.stats.requests += 1;
            answer = transport.get(&url).await;
        }
        let (status, body) = match answer {
            Ok(answer) => answer,
            Err(e) => {
                pace.stats.errors += 1;
                let halt = Halt::Unreachable(e.to_string());
                pace.halted = Some(halt.clone());
                return Ok(Lookup::Halted(halt));
            }
        };
        match status {
            200..=299 | 404 => {}
            429 => {
                pace.halted = Some(Halt::RateLimited);
                return Ok(Lookup::Halted(Halt::RateLimited));
            }
            other if other >= 500 => {
                // A server error halts the build and is not cached; the next build asks
                // again.
                pace.stats.errors += 1;
                let halt = Halt::Unreachable(format!("OpenAlex answered {other}"));
                pace.halted = Some(halt.clone());
                return Ok(Lookup::Halted(halt));
            }
            _ => {
                // Another client error (a malformed request): this lookup gives nothing,
                // is not cached, and the build goes on.
                pace.stats.errors += 1;
                return Ok(Lookup::NotFound);
            }
        }
        let lookup = decode(request, status, &body);
        if matches!(lookup, Lookup::NotFound) {
            pace.stats.not_found += 1;
        }
        drop(pace);
        let ttl = if matches!(lookup, Lookup::Works(_)) {
            POSITIVE_TTL_DAYS
        } else {
            NEGATIVE_TTL_DAYS
        };
        let db = self.db.clone();
        let stored_body = if status == 404 { Vec::new() } else { body };
        blocking(move || db.cache_answer(&key, status, &stored_body, ttl)).await?;
        Ok(lookup)
    }
}

fn decode(request: &WorkRequest, status: u16, body: &[u8]) -> Lookup {
    if status == 404 {
        return Lookup::NotFound;
    }
    let Ok(value) = serde_json::from_slice::<Value>(body) else {
        return Lookup::NotFound;
    };
    let works = match request {
        WorkRequest::Doi(_) => parse_work(&value).into_iter().collect(),
        WorkRequest::Title { .. } => parse_work_list(&value),
    };
    if works.is_empty() {
        Lookup::NotFound
    } else {
        Lookup::Works(works)
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use std::collections::HashMap;
    use std::sync::atomic::{AtomicUsize, Ordering};

    pub(crate) const FIXTURE: &str = include_str!("fixtures/openalex.json");

    pub(crate) fn fixture(name: &str) -> Value {
        let all: Value = serde_json::from_str(FIXTURE).unwrap();
        all[name].clone()
    }

    /// Answers from recorded JSON by URL; anything else is 404. Counts requests.
    pub(crate) struct Replay {
        pub answers: HashMap<String, (u16, Vec<u8>)>,
        pub requests: AtomicUsize,
    }

    impl Replay {
        pub(crate) fn new(answers: Vec<(WorkRequest, u16, Value)>) -> Self {
            Self {
                answers: answers
                    .into_iter()
                    .map(|(r, s, v)| {
                        (
                            r.url().unwrap().to_string(),
                            (s, serde_json::to_vec(&v).unwrap()),
                        )
                    })
                    .collect(),
                requests: AtomicUsize::new(0),
            }
        }
    }

    #[async_trait::async_trait]
    impl ScholarlyTransport for Replay {
        async fn get(&self, url: &Url) -> Result<(u16, Vec<u8>), WebError> {
            self.requests.fetch_add(1, Ordering::SeqCst);
            Ok(self
                .answers
                .get(url.as_str())
                .cloned()
                .unwrap_or((404, b"<html>Not Found</html>".to_vec())))
        }
    }

    pub(crate) fn temp_db() -> (tempfile::TempDir, Arc<ResearchDb>) {
        let dir = tempfile::tempdir().unwrap();
        let db = ResearchDb::open(&dir.path().join("shodh.db"), None).unwrap();
        (dir, Arc::new(db))
    }

    #[test]
    fn works_parse_with_ids_authors_venue_and_counts() {
        let w = parse_work(&fixture("work_by_arxiv_doi")).unwrap();
        assert_eq!(w.id, "W4399554431");
        assert_eq!(w.arxiv_id.as_deref(), Some("2406.06484"));
        assert_eq!(w.doi.as_deref(), Some("10.48550/arxiv.2406.06484"));
        assert_eq!(w.year, Some(2024));
        assert_eq!(w.authors.first().map(String::as_str), Some("Songlin Yang"));
        let lstm = parse_work(&fixture("work_by_doi")).unwrap();
        assert_eq!(lstm.venue.as_deref(), Some("Neural Computation"));
        assert!(lstm.cited_by_count.unwrap_or(0) > 1000);
        assert_eq!(lstm.arxiv_id, None);
        let found = parse_work_list(&fixture("title_search"));
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].arxiv_id.as_deref(), Some("2102.11174"));
        assert_eq!(
            openalex_id("https://openalex.org/W123"),
            Some("W123".into())
        );
        assert_eq!(openalex_id("https://openalex.org/A123"), None);
    }

    #[test]
    fn requests_have_stable_keys_and_safe_filters() {
        let r = WorkRequest::arxiv("2406.06484");
        assert_eq!(r.cache_key(), "openalex:doi:10.48550/arxiv.2406.06484");
        assert!(r
            .url()
            .unwrap()
            .as_str()
            .starts_with("https://api.openalex.org/works/doi:10.48550/arxiv.2406.06484?select="));
        let t = WorkRequest::Title {
            title: "Linear transformers: secretly, fast | weight programmers".into(),
            year: Some(2021),
        };
        let url = t.url().unwrap();
        let filter = url
            .query_pairs()
            .find(|(k, _)| k == "filter")
            .map(|(_, v)| v.to_string())
            .unwrap();
        assert_eq!(
            filter,
            "title.search:linear transformers secretly fast weight programmers,publication_year:2020-2022"
        );
    }

    #[test]
    fn the_strict_rule_needs_title_year_and_first_author() {
        let work = parse_work_list(&fixture("title_search")).remove(0);
        let query = WorkQuery {
            title: Some("Linear transformers are secretly fast weight programmers".into()),
            year: Some(2021),
            first_surname: Some("schlag".into()),
        };
        assert!(strict_match(&query, &work).accepted());
        let off_by_two = WorkQuery {
            year: Some(2023),
            ..query.clone()
        };
        assert!(!strict_match(&off_by_two, &work).accepted());
        let other_author = WorkQuery {
            first_surname: Some("irie".into()),
            ..query.clone()
        };
        assert!(!strict_match(&other_author, &work).accepted());
        let other_title = WorkQuery {
            title: Some("Linear transformers are secretly kernel machines".into()),
            ..query.clone()
        };
        assert!(!strict_match(&other_title, &work).accepted());
        let no_year = WorkQuery {
            year: None,
            ..query
        };
        assert!(!strict_match(&no_year, &work).accepted());
        assert!(identifier_match(Some("Long short-term memory"), &work).accepted() == false);
        assert!(identifier_match(None, &work).accepted());
    }

    #[tokio::test]
    async fn answers_are_cached_including_not_found_and_429_halts_the_build() {
        let (_dir, db) = temp_db();
        let lstm = WorkRequest::Doi("10.1162/neco.1997.9.8.1735".into());
        let replay = Arc::new(Replay::new(vec![(
            lstm.clone(),
            200,
            fixture("work_by_doi"),
        )]));
        let resolver = Resolver::online(replay.clone(), db.clone()).with_limits(10, Duration::ZERO);
        assert!(matches!(resolver.lookup(&lstm).await.unwrap(), Lookup::Works(w) if w.len() == 1));
        let missing = WorkRequest::Doi("10.9999/none".into());
        assert_eq!(resolver.lookup(&missing).await.unwrap(), Lookup::NotFound);
        assert_eq!(replay.requests.load(Ordering::SeqCst), 2);
        // A second build reads both from the cache.
        let again = Resolver::online(replay.clone(), db.clone()).with_limits(10, Duration::ZERO);
        assert!(matches!(
            again.lookup(&lstm).await.unwrap(),
            Lookup::Works(_)
        ));
        assert_eq!(again.lookup(&missing).await.unwrap(), Lookup::NotFound);
        assert_eq!(replay.requests.load(Ordering::SeqCst), 2);
        assert_eq!(again.stats().await.cache_hits, 2);

        struct TooMany(AtomicUsize);
        #[async_trait::async_trait]
        impl ScholarlyTransport for TooMany {
            async fn get(&self, _url: &Url) -> Result<(u16, Vec<u8>), WebError> {
                self.0.fetch_add(1, Ordering::SeqCst);
                Ok((429, Vec::new()))
            }
        }
        let busy = Arc::new(TooMany(AtomicUsize::new(0)));
        let resolver = Resolver::online(busy.clone(), db).with_limits(10, Duration::ZERO);
        let a = WorkRequest::arxiv("2102.11174");
        let b = WorkRequest::arxiv("2411.12537");
        assert_eq!(
            resolver.lookup(&a).await.unwrap(),
            Lookup::Halted(Halt::RateLimited)
        );
        assert_eq!(
            resolver.lookup(&b).await.unwrap(),
            Lookup::Halted(Halt::RateLimited)
        );
        assert_eq!(
            busy.0.load(Ordering::SeqCst),
            2,
            "one retry after a pause, then halt"
        );
    }

    #[tokio::test]
    async fn a_cache_only_resolver_sends_nothing_and_reads_the_cache() {
        let (_dir, db) = temp_db();
        let lstm = WorkRequest::Doi("10.1162/neco.1997.9.8.1735".into());
        let offline = Resolver::cache_only(db.clone());
        assert!(!offline.is_online());
        assert_eq!(
            offline.lookup(&lstm).await.unwrap(),
            Lookup::Halted(Halt::Offline)
        );
        db.cache_answer(
            &lstm.cache_key(),
            200,
            &serde_json::to_vec(&fixture("work_by_doi")).unwrap(),
            30,
        )
        .unwrap();
        assert!(matches!(
            offline.lookup(&lstm).await.unwrap(),
            Lookup::Works(_)
        ));
        assert_eq!(offline.stats().await.requests, 0);
    }

    #[tokio::test]
    async fn the_budget_caps_requests_per_build() {
        let (_dir, db) = temp_db();
        let replay = Arc::new(Replay::new(Vec::new()));
        let resolver = Resolver::online(replay.clone(), db).with_limits(1, Duration::ZERO);
        assert_eq!(
            resolver
                .lookup(&WorkRequest::arxiv("2102.11174"))
                .await
                .unwrap(),
            Lookup::NotFound
        );
        assert_eq!(
            resolver
                .lookup(&WorkRequest::arxiv("2411.12537"))
                .await
                .unwrap(),
            Lookup::Halted(Halt::Budget)
        );
        assert_eq!(replay.requests.load(Ordering::SeqCst), 1);
    }
}

//! Parsing one bibliography entry into authors, title, year, venue, DOI and arXiv id.
//!
//! Deterministic rules only (regular expressions and the shape of the common styles); no
//! model is involved. Each field carries its own confidence, so a caller can trust the
//! DOI of an entry whose title it could not find.
//!
//! The styles recognised:
//! - **IEEE**: `[1] I. Schlag, K. Irie, and J. Schmidhuber, “Linear transformers …,” in
//!   Proc. ICML, 2021, pp. 9355–9366.` (the title is quoted);
//! - **APA**: `Schlag, I., Irie, K., & Schmidhuber, J. (2021). Linear transformers ….
//!   In Proceedings of ICML.` (the year follows the authors in parentheses);
//! - **ACL**: `Imanol Schlag, Kazuki Irie, and Jürgen Schmidhuber. 2021. Linear
//!   transformers …. In Proceedings of ICML.` (the year follows the authors);
//! - **author–title–year** (NeurIPS, ICML, ICLR and most numbered styles):
//!   `Schlag, I., Irie, K., and Schmidhuber, J. Linear transformers …. In ICML, 2021.`
//!
//! Identifiers are read first and removed before the year is looked for, so the digits of
//! an arXiv id (`2010.11929`) or a DOI are never taken for a year.

use std::sync::LazyLock;

use regex::Regex;
use serde::{Deserialize, Serialize};

use super::text::{clean_block_text, normalize_surname};
use crate::harness::web::papers::{normalize_arxiv_id, normalize_doi};

/// One author as printed.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AuthorName {
    /// Given names or initials as printed (`Kazuki`, `K.`, `J.-P.`), possibly empty.
    pub given: String,
    /// Family name as printed (`Irie`, `van den Oord`).
    pub family: String,
}

impl AuthorName {
    /// `Given Family`, or the family name alone.
    pub fn display(&self) -> String {
        if self.given.is_empty() {
            self.family.clone()
        } else {
            format!("{} {}", self.given, self.family)
        }
    }

    /// Comparable surname (diacritics folded, letters only, lower case). For a name with
    /// particles (`van den Oord`) this is the last word (`oord`).
    pub fn surname_key(&self) -> String {
        let last = self
            .family
            .split_whitespace()
            .last()
            .unwrap_or(&self.family);
        normalize_surname(last)
    }
}

/// The citation style an entry was read as.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CitationStyle {
    /// Quoted title.
    Ieee,
    /// `Authors (Year). Title.`
    Apa,
    /// `Authors. Year. Title.`
    Acl,
    /// `Authors. Title. Venue, Year.`
    AuthorTitleYear,
    /// Only identifiers or fragments could be read.
    Unknown,
}

/// Confidence in `[0, 1]` of each parsed field (`0` when the field is absent).
#[derive(Debug, Clone, Copy, PartialEq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FieldConfidence {
    pub authors: f64,
    pub title: f64,
    pub year: f64,
    pub venue: f64,
    pub doi: f64,
    pub arxiv_id: f64,
}

/// One parsed bibliography entry.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ParsedReference {
    /// The entry as one line (ligatures expanded, line-break hyphens joined), with its
    /// leading marker (`[12]`, `12.`) removed.
    pub text: String,
    /// The marker as printed (`12`, `Vas+17`), when the entry has one.
    pub marker: Option<String>,
    pub authors: Vec<AuthorName>,
    /// The list ended with `et al.` (more authors than printed).
    pub et_al: bool,
    pub title: Option<String>,
    pub year: Option<i32>,
    pub venue: Option<String>,
    /// Lower-cased DOI (`10.1234/abc`).
    pub doi: Option<String>,
    /// arXiv id without version (`2102.11174`).
    pub arxiv_id: Option<String>,
    pub style: CitationStyle,
    pub confidence: FieldConfidence,
}

impl ParsedReference {
    /// Comparable surname of the first author.
    pub fn first_surname(&self) -> Option<String> {
        self.authors
            .first()
            .map(AuthorName::surname_key)
            .filter(|s| !s.is_empty())
    }

    /// Whether the entry identifies a work well enough to become a graph node: an
    /// identifier, or a title with a year or an author.
    pub fn is_identifiable(&self) -> bool {
        if self.doi.is_some() || self.arxiv_id.is_some() {
            return true;
        }
        let Some(title) = &self.title else {
            return false;
        };
        // Without authors, only a title-shaped text counts (not `pages 1–10`).
        let titled = !self.authors.is_empty()
            || (title.split_whitespace().count() >= 3
                && title.chars().next().is_some_and(char::is_uppercase));
        titled && self.confidence.title >= 0.5 && (self.year.is_some() || !self.authors.is_empty())
    }

    /// Overall confidence: the weakest of the fields that identify the work.
    pub fn confidence_overall(&self) -> f64 {
        if self.doi.is_some() || self.arxiv_id.is_some() {
            return self.confidence.doi.max(self.confidence.arxiv_id);
        }
        let mut c = self.confidence.title;
        if self.year.is_some() {
            c = c.min(self.confidence.year.max(0.5));
        }
        if !self.authors.is_empty() {
            c = c.min(self.confidence.authors.max(0.5));
        }
        c
    }
}

static RE_MARKER: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(
        r"^\s*(?:\[(?P<a>[A-Za-z0-9+.\- ]{1,12})\]|\((?P<b>\d{1,4})\)|(?P<c>\d{1,4})\.(?:\s|$))\s*",
    )
    .ok()
}));
static RE_DOI: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r"(?i)(?:https?://(?:dx\.)?doi\.org/|doi:\s*)?(?P<doi>10\.\d{4,9}/[^\s,;]+)").ok()
}));
static RE_ARXIV: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(
        r"(?i)(?:arxiv\s*(?:preprint)?\s*[: ]\s*(?:arxiv:)?\s*|arxiv\.org/(?:abs|pdf)/|corr,?\s*abs/|\babs/)(?P<id>\d{4}\.\d{4,5}(?:v\d+)?|[a-z\-]+(?:\.[a-z]{2})?/\d{7}(?:v\d+)?)",
    )
    .ok()
}));
static RE_URL: Pattern = Pattern(LazyLock::new(|| Regex::new(r"(?i)\bhttps?://\S+").ok()));
static RE_YEAR: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r"(?:^|[^0-9A-Za-z])(?P<y>(?:19[5-9]\d|20[0-4]\d))[a-z]?(?:[^0-9]|$)").ok()
}));
static RE_LEADING_YEAR: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r"^\(?(?P<y>(?:19[5-9]\d|20[0-4]\d))[a-z]?\)?(?:\s*[.,:]|\s|$)\s*").ok()
}));
static RE_QUOTED: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r#"[“"‘'']{1,2}(?P<t>[^“”"]{8,400}?)[,.]?\s*[”"’'']{1,2}"#).ok()
}));
/// A given-name token: a capitalised word, an initial with its period (`J.`, `J.-P.`) or
/// a bare initial.
const GIVEN: &str = r"(?:\p{Lu}[\p{Ll}\p{Lo}'’\-]+(?:\p{Lu}[\p{Ll}]+)*(?:-\p{Lu}[\p{Ll}]+)?|\p{Lu}\.(?:\s?-?\p{Lu}\.)*|\p{Lu}(?:\s|$))";
/// A family name, with lower-case particles (`van den Oord`, `de Freitas`).
const FAMILY: &str = r"(?:(?:van|von|der|den|de|del|della|da|di|du|dos|das|la|le|ten|ter|al|el|bin|ibn)\s+)*(?:\p{Lu}[\p{L}'’\-]*\p{L}|\p{Lu}\p{Ll}?)";
static RE_SURNAME_FIRST: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(&format!(
        r"^(?P<family>{FAMILY}),\s*(?P<given>\p{{Lu}}\.(?:\s?-?\p{{Lu}}\.)*|(?:\p{{Lu}}[\p{{Ll}}\-]+)(?:\s+\p{{Lu}}\.)*)"
    ))
    .ok()
}));
static RE_GIVEN_FIRST: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(&format!(
        r"^(?P<given>(?:{GIVEN}\s*){{1,4}}?)\s*(?P<family>{FAMILY})(?:\s+(?:Jr\.|Sr\.|II|III|IV))?"
    ))
    .ok()
}));
/// A further family-name word right after a given-first name (`Florencia Leoni Aleman`,
/// `Alexei A Efros`): the name continues when a separator or the list's end follows it.
static RE_NAME_CONTINUES: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(&format!(r"^\s+(?P<family>{FAMILY})")).ok()
}));
static RE_SEPARATOR: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r"^(?:\s*,\s*(?:and\s+|&\s*)?|\s+(?:and|&)\s+|\s*;\s*)").ok()
}));
static RE_ET_AL: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(r"^\s*,?\s*(?:et\s*al\.?|and\s+others\.?)").ok()
}));
static RE_VENUE_TAIL: Pattern = Pattern(LazyLock::new(|| {
    Regex::new(
        r"(?i)(?:,|\.)?\s*(?:pp?\.\s*\d|pages?\s+\d|vol(?:ume)?\.?\s*\d|no\.\s*\d|\(\s*\d{1,4}\s*\)|\d+\s*\(\d+\)|\d+\s*[–-]\s*\d+|(?:19[5-9]\d|20[0-4]\d)\b|url\b|issn\b|isbn\b|publisher\b|$)",
    )
    .ok()
}));

/// A compiled pattern. Every pattern is a literal checked by the tests; should one fail to
/// compile, it matches nothing and the parser degrades instead of panicking.
struct Pattern(LazyLock<Option<Regex>>);

impl Pattern {
    fn get(&self) -> Option<&Regex> {
        self.0.as_ref()
    }

    fn is_match(&self, text: &str) -> bool {
        self.get().is_some_and(|r| r.is_match(text))
    }

    fn find<'t>(&self, text: &'t str) -> Option<regex::Match<'t>> {
        self.get().and_then(|r| r.find(text))
    }

    fn captures<'t>(&self, text: &'t str) -> Option<regex::Captures<'t>> {
        self.get().and_then(|r| r.captures(text))
    }

    fn captures_iter<'t>(&self, text: &'t str) -> Vec<regex::Captures<'t>> {
        self.get()
            .map(|r| r.captures_iter(text).collect())
            .unwrap_or_default()
    }

    fn replace_all(&self, text: &str, with: &str) -> String {
        match self.get() {
            Some(r) => r.replace_all(text, with).to_string(),
            None => text.to_string(),
        }
    }
}

